CREATE FUNCTION dvnt_settlement.wake_checkout_reconciliation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF ROW(NEW.status,NEW.stripe_payment_intent_id,NEW.stripe_checkout_session_id)
 IS DISTINCT FROM ROW(OLD.status,OLD.stripe_payment_intent_id,OLD.stripe_checkout_session_id) THEN
  UPDATE dvnt_settlement.checkouts SET next_check_at=NULL,retired_at=NULL,reconciliation_attempts=0 WHERE order_id=NEW.id;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.wake_checkout_reconciliation() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER wake_settlement_checkout AFTER UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.wake_checkout_reconciliation();

-- Only a trusted adapter's freshly retrieved, fully bound PI can establish a
-- known nonpaid observation. Null/malformed/contradictory proof fails closed.
-- This RPC never clears a hold, reservation, allocation, or financial evidence.
CREATE FUNCTION public.settlement_checkout_observation(p_order_id uuid,p_outcome text,p_intent jsonb DEFAULT NULL,p_session jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE; c dvnt_settlement.checkouts%ROWTYPE; gross bigint; attempts int; retire boolean:=false;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=p_order_id FOR UPDATE;
 IF o.charge_model IS DISTINCT FROM 'separate_charges_and_transfers' OR c.attempted_at IS NULL
  OR p_outcome IS NULL OR p_outcome NOT IN ('unknown','nonpaid') THEN RAISE EXCEPTION 'invalid checkout observation'; END IF;
 attempts:=least(c.reconciliation_attempts+1,20);
 IF p_outcome='unknown' THEN
  UPDATE dvnt_settlement.checkouts SET outcome_unknown_since=coalesce(outcome_unknown_since,now()),retired_at=NULL,
   reconciliation_attempts=attempts,next_check_at=now()+make_interval(secs=>least(3600,300*power(2,least(attempts-1,4)))::int)
   WHERE order_id=p_order_id;
 ELSE
  gross:=(c.snapshot->'order'->>'total_cents')::bigint;
  IF c.snapshot->>'rail' IN ('ticket-checkout','guest-checkout') AND o.stripe_checkout_session_id IS NULL
   THEN RAISE EXCEPTION 'hosted nonpaid observation requires exact session proof'; END IF;
  IF o.stripe_checkout_session_id IS NOT NULL THEN
   IF p_session IS NULL OR jsonb_typeof(p_session)<>'object'
    OR p_session->>'id' IS DISTINCT FROM o.stripe_checkout_session_id
    OR p_session->>'id' !~ '^cs_[A-Za-z0-9_]+$'
    OR p_session->'metadata'->>'settlement_order_id' IS DISTINCT FROM o.id::text
    OR p_session->'metadata'->>'charge_model' IS DISTINCT FROM o.charge_model
    OR p_session->>'currency' IS DISTINCT FROM o.currency
    OR p_session->'amount_subtotal' IS DISTINCT FROM to_jsonb(gross)
    OR p_session->>'payment_intent' IS DISTINCT FROM o.stripe_payment_intent_id
    OR p_session->>'payment_status' IS DISTINCT FROM 'unpaid'
    OR p_session->>'status' IS NULL OR p_session->>'status' NOT IN ('open','complete','expired')
    OR jsonb_typeof(p_session->'total_details'->'amount_tax') IS DISTINCT FROM 'number'
    OR (p_session->'total_details'->>'amount_tax')::bigint<0
    OR p_session->'total_details'->'amount_discount' IS DISTINCT FROM '0'::jsonb
    OR p_session->'total_details'->'amount_shipping' IS DISTINCT FROM '0'::jsonb
   THEN RAISE EXCEPTION 'invalid nonpaid session proof'; END IF;
   gross:=gross+(p_session->'total_details'->>'amount_tax')::bigint;
   IF p_session->'amount_total' IS DISTINCT FROM to_jsonb(gross) THEN RAISE EXCEPTION 'invalid nonpaid session amount'; END IF;
  ELSIF p_session IS NOT NULL THEN RAISE EXCEPTION 'unexpected session proof'; END IF;
  IF p_intent IS NULL OR jsonb_typeof(p_intent)<>'object' OR o.stripe_payment_intent_id IS NULL
   OR p_intent->>'id' IS DISTINCT FROM o.stripe_payment_intent_id
   OR p_intent->>'id' !~ '^pi_[A-Za-z0-9_]+$'
   OR p_intent->'metadata'->>'settlement_order_id' IS DISTINCT FROM o.id::text
   OR p_intent->'metadata'->>'charge_model' IS DISTINCT FROM o.charge_model
   OR p_intent->>'currency' IS DISTINCT FROM o.currency
   OR p_intent->'amount' IS DISTINCT FROM to_jsonb(gross)
   OR p_intent->'amount_received' IS DISTINCT FROM '0'::jsonb
   OR p_intent->'latest_charge' IS DISTINCT FROM 'null'::jsonb
   OR p_intent->>'status' IS NULL OR p_intent->>'status' NOT IN ('requires_payment_method','requires_confirmation','requires_action','processing','requires_capture','canceled')
   OR coalesce(p_intent->'transfer_data','null'::jsonb)<>'null'::jsonb
   OR coalesce(p_intent->'application_fee_amount','null'::jsonb)<>'null'::jsonb
   OR coalesce(p_intent->'on_behalf_of','null'::jsonb)<>'null'::jsonb
   OR o.status IS NULL OR o.status NOT IN ('created','payment_pending','payment_failed','canceled','cancelled','failed')
   OR o.paid_at IS NOT NULL OR c.source_verified_at IS NOT NULL
   OR EXISTS(SELECT 1 FROM dvnt_settlement.orders WHERE order_id=o.id)
   OR EXISTS(SELECT 1 FROM dvnt_settlement.allocations WHERE order_id=o.id)
  THEN RAISE EXCEPTION 'invalid nonpaid intent proof'; END IF;
  retire:=p_intent->>'status'='canceled'
   AND (o.stripe_checkout_session_id IS NULL OR p_session->>'status'='expired')
   AND coalesce(c.last_error,'') NOT LIKE 'hold:%'
   AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.holds WHERE order_id=o.id);
  UPDATE dvnt_settlement.checkouts SET outcome_unknown_since=NULL,reconciliation_attempts=attempts,
   retired_at=CASE WHEN retire THEN now() ELSE NULL END,
   next_check_at=least(now()+make_interval(secs=>least(21600,300*power(2,least(attempts-1,7)))::int),
    greatest(now(),greatest(c.release_not_before,dvnt_settlement.event_release_at(o.event_id)))+interval '1 hour')
   WHERE order_id=p_order_id;
 END IF;
 RETURN jsonb_build_object('ok',true,'retired',retire);
END $$;


CREATE FUNCTION dvnt_settlement.freeze_prepared_order() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c dvnt_settlement.checkouts%ROWTYPE;
BEGIN
 SELECT * INTO c FROM dvnt_settlement.checkouts WHERE order_id=OLD.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF ROW(NEW.charge_model,NEW.subtotal_cents,NEW.organizer_fee_cents,NEW.promoter_commission_amount_cents,
  NEW.promoter_id,NEW.promoter_code,NEW.event_id,NEW.user_id,NEW.guest_email,NEW.type,NEW.currency,NEW.quantity,NEW.cart_id)
 IS DISTINCT FROM ROW(OLD.charge_model,OLD.subtotal_cents,OLD.organizer_fee_cents,OLD.promoter_commission_amount_cents,
  OLD.promoter_id,OLD.promoter_code,OLD.event_id,OLD.user_id,OLD.guest_email,OLD.type,OLD.currency,OLD.quantity,OLD.cart_id)
 OR (OLD.stripe_payment_intent_id IS NOT NULL AND NEW.stripe_payment_intent_id IS DISTINCT FROM OLD.stripe_payment_intent_id)
 OR (OLD.stripe_checkout_session_id IS NOT NULL AND NEW.stripe_checkout_session_id IS DISTINCT FROM OLD.stripe_checkout_session_id)
 OR NEW.tax_cents<0 OR NEW.total_cents IS DISTINCT FROM (c.snapshot->'order'->>'total_cents')::bigint+coalesce(NEW.tax_cents,0)
 THEN RAISE EXCEPTION 'prepared checkout economics and identity are immutable'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.freeze_prepared_order() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER freeze_prepared_settlement BEFORE UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.freeze_prepared_order();

CREATE FUNCTION dvnt_settlement.bind_allocation_identity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c dvnt_settlement.checkouts%ROWTYPE;
BEGIN
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=NEW.order_id;
 IF NEW.role='organizer' THEN NEW.recipient_id:=c.organizer_user_id; NEW.recipient_user_id:=c.organizer_user_id;
 ELSE
  IF c.promoter_id IS NULL THEN RAISE EXCEPTION 'missing locked promoter identity'; END IF;
  NEW.recipient_id:=c.promoter_id::text; NEW.recipient_user_id:=c.promoter_user_id;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.bind_allocation_identity() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER bind_settlement_recipient BEFORE INSERT ON dvnt_settlement.allocations
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.bind_allocation_identity();

-- The same catalog item can arrive through hosted, native or cart checkout.
-- IDs of cart lines and request keys are attempt identities, not a different
-- purchase. Unknown selection shapes fail closed for this buyer/event only.
CREATE FUNCTION dvnt_settlement.checkout_selections_overlap(p_left jsonb,p_right jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE selection jsonb; line jsonb; targets text[]; left_targets text[]; side int:=0;
BEGIN
 FOREACH selection IN ARRAY ARRAY[p_left,p_right] LOOP
  side:=side+1; targets:='{}';
  IF jsonb_typeof(selection) IS DISTINCT FROM 'object' THEN RETURN true; END IF;
  IF nullif(selection->>'ticket_type_id','') IS NOT NULL THEN
   targets:=array_append(targets,'tier:'||((selection->>'ticket_type_id')::uuid)::text);
  END IF;
  IF selection ? 'lines' THEN
   IF jsonb_typeof(selection->'lines') IS DISTINCT FROM 'array' THEN RETURN true; END IF;
   FOR line IN SELECT value FROM jsonb_array_elements(selection->'lines') LOOP
    IF jsonb_typeof(line) IS DISTINCT FROM 'object' THEN RETURN true; END IF;
    IF nullif(line->>'tier_id','') IS NOT NULL AND nullif(line->>'addon_id','') IS NULL THEN
     targets:=array_append(targets,'tier:'||((line->>'tier_id')::uuid)::text);
    ELSIF nullif(line->>'addon_id','') IS NOT NULL AND nullif(line->>'tier_id','') IS NULL THEN
     targets:=array_append(targets,'addon:'||((line->>'addon_id')::uuid)::text||':variant:'||coalesce((nullif(line->>'variant_id','')::uuid)::text,''));
    ELSE RETURN true;
    END IF;
   END LOOP;
  END IF;
  IF cardinality(targets)=0 THEN RETURN true; END IF;
  IF side=1 THEN left_targets:=targets; END IF;
 END LOOP;
 RETURN left_targets && targets;
EXCEPTION WHEN invalid_text_representation THEN
 -- PostgreSQL accepts multiple spellings of a UUID. Malformed historical
 -- selections cannot safely establish that two pending purchases differ.
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.checkout_selections_overlap(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.prepare_settlement_checkout(p_snapshot jsonb,p_request_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v jsonb:=p_snapshot->'order'; c dvnt_settlement.checkouts%ROWTYPE;
 o public.orders%ROWTYPE; scope text; host text; release_at timestamptz; delay_seconds integer; promoter public.event_promoters%ROWTYPE;
BEGIN
 IF NOT (SELECT checkout_enabled FROM dvnt_settlement.controls WHERE singleton) THEN RAISE EXCEPTION 'separate checkout disabled'; END IF;
 IF v IS NULL OR jsonb_typeof(v)<>'object' OR p_snapshot->>'rail' IS NULL
 OR v->>'total_cents' IS NULL OR v->>'quantity' IS NULL OR v->>'subtotal_cents' IS NULL
 OR v->>'organizer_fee_cents' IS NULL OR v->>'event_id' IS NULL OR v->>'currency' IS NULL
 OR p_request_key IS NULL OR length(p_request_key)<16 OR length(p_request_key)>128
 OR p_snapshot->>'rail' NOT IN ('ticket-checkout','guest-checkout','cart-checkout','create-payment-intent')
 OR coalesce(v->>'user_id',v->>'guest_email','')='' OR (v->>'total_cents')::bigint<=0
 OR (v->>'quantity')::int<=0 OR (v->>'subtotal_cents')::bigint<0
 OR (v->>'organizer_fee_cents')::bigint<0 OR v->>'currency' !~ '^[a-z]{3}$' THEN RAISE EXCEPTION 'invalid checkout snapshot'; END IF;
 scope:=(p_snapshot->>'rail')||':'||coalesce(v->>'user_id',lower(v->>'guest_email'))||':'||p_request_key;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(scope,0));
 SELECT * INTO c FROM dvnt_settlement.checkouts WHERE request_scope=scope FOR UPDATE;
 IF FOUND THEN
  IF c.snapshot IS DISTINCT FROM p_snapshot THEN RAISE EXCEPTION 'checkout replay mismatch'; END IF;
  IF v->>'user_id' IS NULL THEN RAISE EXCEPTION 'guest replay requires secure recovery'; END IF;
  SELECT * INTO STRICT o FROM public.orders WHERE id=c.order_id;
 ELSE
  -- A remounted client that lost its key cannot silently create a second
  -- payment for the same selection while the earlier outcome is unresolved.
  -- All paid rails share this mutex. Rail-scoped locks allow simultaneous
  -- hosted/native requests to both observe no prior attempt and charge twice.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('checkout:'||
   CASE WHEN v->>'user_id' IS NOT NULL THEN 'member:'||(v->>'user_id') ELSE 'guest:'||lower(v->>'guest_email') END||':'||((v->>'event_id')::int)::text,1));
  IF EXISTS(SELECT 1 FROM dvnt_settlement.checkouts prior JOIN public.orders old ON old.id=prior.order_id
   WHERE dvnt_settlement.checkout_selections_overlap(prior.snapshot->'selection',p_snapshot->'selection')
   AND old.event_id=(v->>'event_id')::int AND old.status IS DISTINCT FROM 'paid'
   AND (CASE WHEN v->>'user_id' IS NOT NULL THEN old.user_id=v->>'user_id' ELSE old.user_id IS NULL AND lower(old.guest_email)=lower(v->>'guest_email') END))
  THEN RAISE EXCEPTION 'existing checkout requires reconciliation'; END IF;
  IF v->>'cart_id' IS NOT NULL THEN
   PERFORM 1 FROM public.carts WHERE id=(v->>'cart_id')::uuid FOR UPDATE;
   IF EXISTS(SELECT 1 FROM public.orders WHERE cart_id=(v->>'cart_id')::uuid) THEN RAISE EXCEPTION 'cart already has payment'; END IF;
  END IF;
  SELECT host_id::text,dvnt_settlement.event_release_at(id) INTO STRICT host,release_at FROM public.events WHERE id=(v->>'event_id')::int FOR SHARE;
  IF release_at IS NULL OR NOT isfinite(release_at) THEN RAISE EXCEPTION 'event end missing'; END IF;
  IF host IS NULL THEN RAISE EXCEPTION 'organizer identity missing'; END IF;
  IF v->>'promoter_code' IS NOT NULL THEN
   SELECT * INTO STRICT promoter FROM public.event_promoters WHERE event_id=(v->>'event_id')::int
    AND upper(code)=upper(v->>'promoter_code') AND status='active' FOR SHARE;
   IF (v->>'promoter_commission_amount_cents') IS NULL OR
      (v->>'promoter_commission_bps')::int IS DISTINCT FROM promoter.promoter_commission_bps OR
      (v->>'promoter_customer_discount_bps')::int IS DISTINCT FROM promoter.customer_discount_bps THEN
    RAISE EXCEPTION 'promoter snapshot changed';
   END IF;
  END IF;
  IF (coalesce((v->>'promoter_commission_amount_cents')::bigint,0)>0 AND promoter.id IS NULL)
   OR coalesce((v->>'promoter_commission_amount_cents')::bigint,0)<0 OR
   coalesce((v->>'promoter_commission_amount_cents')::bigint,0)>(v->>'subtotal_cents')::bigint-(v->>'organizer_fee_cents')::bigint THEN
   RAISE EXCEPTION 'commission exceeds organizer allocation'; END IF;
  INSERT INTO public.orders(user_id,guest_email,guest_phone,type,status,charge_model,event_id,quantity,currency,
   subtotal_cents,total_cents,platform_fee_cents,buyer_pct_fee_cents,buyer_per_ticket_fee_cents,buyer_fee_cents,
   org_pct_fee_cents,org_per_ticket_fee_cents,organizer_fee_cents,dvnt_total_fee_cents,fee_policy_version,
   cart_id,promo_code_id,discount_cents,promoter_id,promoter_code,promoter_policy_version,promoter_original_amount_cents,
   promoter_customer_discount_bps,promoter_discount_amount_cents,promoter_discounted_amount_cents,
   promoter_commission_bps,promoter_commission_amount_cents)
  VALUES(v->>'user_id',lower(v->>'guest_email'),v->>'guest_phone','event_ticket','payment_pending','separate_charges_and_transfers',
   (v->>'event_id')::int,(v->>'quantity')::int,v->>'currency',(v->>'subtotal_cents')::int,(v->>'total_cents')::int,
   (v->>'platform_fee_cents')::int,(v->>'buyer_pct_fee_cents')::int,(v->>'buyer_per_ticket_fee_cents')::int,(v->>'buyer_fee_cents')::int,
   (v->>'org_pct_fee_cents')::int,(v->>'org_per_ticket_fee_cents')::int,(v->>'organizer_fee_cents')::int,(v->>'dvnt_total_fee_cents')::int,v->>'fee_policy_version',
   (v->>'cart_id')::uuid,(v->>'promo_code_id')::uuid,(v->>'discount_cents')::int,promoter.id,v->>'promoter_code',v->>'promoter_policy_version',
   (v->>'promoter_original_amount_cents')::int,(v->>'promoter_customer_discount_bps')::int,(v->>'promoter_discount_amount_cents')::int,
   (v->>'promoter_discounted_amount_cents')::int,(v->>'promoter_commission_bps')::int,(v->>'promoter_commission_amount_cents')::int)
  RETURNING * INTO o;
  IF promoter.id IS NOT NULL THEN
   INSERT INTO public.promoter_attributions(order_id,promoter_id,locked_rev_share_bps,locked_customer_discount_bps,
    locked_promoter_commission_bps,locked_promoter_discount_amount_cents,locked_promoter_commission_amount_cents)
   VALUES(o.id,promoter.id,coalesce(promoter.rev_share_bps,0),promoter.customer_discount_bps,promoter.promoter_commission_bps,
    o.promoter_discount_amount_cents,o.promoter_commission_amount_cents);
  END IF;
  INSERT INTO dvnt_settlement.checkouts(order_id,request_scope,snapshot,release_not_before,organizer_user_id,promoter_id,promoter_user_id) VALUES(o.id,scope,p_snapshot,release_at,host,promoter.id,promoter.user_id) RETURNING * INTO c;
 END IF;
 RETURN jsonb_build_object('ok',true,'order_id',o.id,'charge_model',o.charge_model,
  'idempotency_key','dvnt:checkout:v1:'||o.id::text,'created_at',c.created_at,
  'stripe_payment_intent_id',o.stripe_payment_intent_id,'stripe_checkout_session_id',o.stripe_checkout_session_id);
END $$;

CREATE FUNCTION public.claim_settlement_checkout(p_order_id uuid,p_params jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c dvnt_settlement.checkouts%ROWTYPE;
BEGIN
 PERFORM 1 FROM public.orders WHERE id=p_order_id FOR UPDATE;
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=p_order_id FOR UPDATE;
 IF NOT (SELECT checkout_enabled FROM dvnt_settlement.controls WHERE singleton) THEN RAISE EXCEPTION 'checkout disabled'; END IF;
 IF c.attempted_at IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'claimed',false); END IF;
 IF p_params IS NULL OR jsonb_typeof(p_params)<>'object' THEN RAISE EXCEPTION 'missing provider params'; END IF;
 UPDATE dvnt_settlement.checkouts SET stripe_params=p_params,attempted_at=now() WHERE order_id=p_order_id;
 RETURN jsonb_build_object('ok',true,'claimed',true,'idempotency_key','dvnt:checkout:v1:'||p_order_id::text);
END $$;

CREATE FUNCTION public.finalize_settlement_checkout(p_order_id uuid,p_payment_intent_id text,p_checkout_session_id text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 IF o.charge_model IS DISTINCT FROM 'separate_charges_and_transfers' OR
  NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts WHERE order_id=o.id AND attempted_at IS NOT NULL) OR
  (p_payment_intent_id IS NULL AND p_checkout_session_id IS NULL) OR
  (p_payment_intent_id IS NOT NULL AND p_payment_intent_id !~ '^pi_[A-Za-z0-9_]+$') OR
  (p_checkout_session_id IS NOT NULL AND p_checkout_session_id !~ '^cs_[A-Za-z0-9_]+$') OR
  (o.stripe_payment_intent_id IS NOT NULL AND p_payment_intent_id IS DISTINCT FROM o.stripe_payment_intent_id) OR
  (o.stripe_checkout_session_id IS NOT NULL AND p_checkout_session_id IS DISTINCT FROM o.stripe_checkout_session_id)
 THEN RAISE EXCEPTION 'payment linkage mismatch'; END IF;
 UPDATE public.orders SET stripe_payment_intent_id=coalesce(p_payment_intent_id,stripe_payment_intent_id),
  stripe_checkout_session_id=coalesce(p_checkout_session_id,stripe_checkout_session_id) WHERE id=o.id;
 -- A freshly verified webhook may repeat the same linkage after a backoff.
 -- Wake observation only; it cannot clear holds or establish source funding.
 UPDATE dvnt_settlement.checkouts SET next_check_at=NULL,retired_at=NULL,reconciliation_attempts=0 WHERE order_id=o.id;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE FUNCTION public.settlement_candidates(p_limit int DEFAULT 100,p_order_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE chosen uuid[]; n int:=greatest(1,least(coalesce(p_limit,100),100)); v_turn int; quotas int[];
BEGIN
 IF p_order_id IS NULL THEN
  SELECT q.turn INTO v_turn FROM dvnt_settlement.queue_cursor q WHERE singleton FOR UPDATE;
  quotas:=CASE WHEN n>=4 THEN ARRAY[greatest(1,n*25/100),n-greatest(1,n*25/100)-2*greatest(1,n*15/100),greatest(1,n*15/100),greatest(1,n*15/100)]
   ELSE ARRAY[0,0,0,0] END;
  IF n<4 THEN
   FOR i IN 0..n-1 LOOP quotas[1+(v_turn+i)%4]:=1; END LOOP;
   UPDATE dvnt_settlement.queue_cursor SET turn=(v_turn+n)%4 WHERE singleton;
  END IF;
  WITH releases AS MATERIALIZED (
   SELECT e.id,dvnt_settlement.event_release_at(e.id) AS release_at FROM public.events e
   WHERE EXISTS(SELECT 1 FROM public.orders o JOIN dvnt_settlement.checkouts c ON c.order_id=o.id
    WHERE o.event_id=e.id AND c.attempted_at IS NOT NULL)
  ), eligible AS (
   SELECT c.order_id,c.last_checked_at,c.created_at,
    CASE WHEN EXISTS(SELECT 1 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
      WHERE a.order_id=o.id AND d.state IN ('reserved','uncertain','recovery_required')) THEN 1
     WHEN s.order_id IS NOT NULL THEN 2
     WHEN greatest(c.release_not_before,r.release_at)<=now()
      AND (c.outcome_unknown_since IS NOT NULL OR o.status IN ('paid','partially_refunded','refunded','disputed')) THEN 3 ELSE 4 END AS bucket
   FROM dvnt_settlement.checkouts c JOIN public.orders o ON o.id=c.order_id LEFT JOIN dvnt_settlement.orders s ON s.order_id=o.id JOIN releases r ON r.id=o.event_id
   WHERE o.charge_model='separate_charges_and_transfers' AND c.attempted_at IS NOT NULL
    AND ((s.order_id IS NULL AND c.retired_at IS NULL AND (c.next_check_at IS NULL OR c.next_check_at<=now()))
     OR EXISTS(SELECT 1 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
      WHERE a.order_id=o.id AND (d.state IN ('reserved','uncertain','recovery_required')
       OR (d.state='held' AND greatest(s.release_at,r.release_at)<=now()
        AND NOT (a.role='promoter' AND dvnt_settlement.promoter_obligation_satisfied(a.id))))))
  ), ranked AS (
   SELECT *,row_number() OVER(PARTITION BY bucket ORDER BY last_checked_at NULLS FIRST,created_at,order_id) AS rank FROM eligible
  )
  SELECT ARRAY(SELECT c.order_id FROM ranked r JOIN dvnt_settlement.checkouts c ON c.order_id=r.order_id
   ORDER BY CASE WHEN r.rank<=quotas[r.bucket] THEN 0 ELSE 1 END,r.bucket,r.rank
   LIMIT n FOR UPDATE OF c SKIP LOCKED) INTO chosen;
  UPDATE dvnt_settlement.checkouts SET last_checked_at=clock_timestamp(),
   next_check_at=CASE WHEN NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders s WHERE s.order_id=checkouts.order_id)
    THEN now()+interval '5 minutes' ELSE next_check_at END WHERE order_id=ANY(chosen);
 ELSE chosen:=ARRAY[p_order_id]; END IF;
 -- Preserve dispatch priority, not just batch membership: the worker consumes
 -- this JSON sequentially and older pending attempts must not jump the queue.
 RETURN (SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY array_position(chosen,t.order_id)),'[]'::jsonb) FROM (
 SELECT o.id AS order_id,o.status,o.stripe_payment_intent_id,o.stripe_checkout_session_id,
  c.snapshot,c.created_at,c.attempted_at,c.stripe_params,e.payout_release_at,e.host_id,
  e.payout_status,EXISTS(SELECT 1 FROM dvnt_settlement.orders s WHERE s.order_id=o.id) AS enrolled,
  coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'role',a.role,'recipient_id',a.recipient_id,'recipient_user_id',a.recipient_user_id,
   'amount_cents',a.amount_cents,'state',d.state,'destination',d.destination,'stripe_transfer_id',d.stripe_transfer_id,
   'idempotency_key',d.idempotency_key,'charge_id',s.charge_id,'currency',s.currency,
   'obligation_satisfied',CASE WHEN a.role='promoter' THEN dvnt_settlement.promoter_obligation_satisfied(a.id) ELSE false END,
   'candidate_destination',CASE WHEN a.role='organizer' THEN
     (SELECT oa.stripe_account_id FROM public.organizer_accounts oa WHERE oa.host_id=a.recipient_id LIMIT 1)
    ELSE (SELECT coalesce(ep.stripe_account_id,(SELECT oa.stripe_account_id FROM public.organizer_accounts oa WHERE oa.host_id=a.recipient_user_id LIMIT 1))
      FROM public.event_promoters ep WHERE ep.id::text=a.recipient_id) END))
   FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
   JOIN dvnt_settlement.orders s ON s.order_id=a.order_id WHERE a.order_id=o.id),'[]'::jsonb) AS allocations
 FROM dvnt_settlement.checkouts c JOIN public.orders o ON o.id=c.order_id JOIN public.events e ON e.id=o.event_id
 WHERE o.charge_model='separate_charges_and_transfers' AND c.attempted_at IS NOT NULL
 AND o.id=ANY(chosen)
 AND (p_order_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders s WHERE s.order_id=o.id)
  OR EXISTS(SELECT 1 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
   WHERE a.order_id=o.id AND d.state IN ('held','reserved','uncertain','recovery_required')))
 ) t);
END $$;

CREATE FUNCTION public.settlement_order(p_order_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT public.settlement_candidates(100,p_order_id)->0;
$$;

CREATE FUNCTION public.settlement_verify_source(p_order_id uuid,p_charge text,p_pi text,p_currency text,p_gross bigint,p_tax bigint DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE;c dvnt_settlement.checkouts%ROWTYPE; v_release_at timestamptz; existing_release timestamptz; delay_seconds int;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 -- Serialize the liability representation change with every currency budget read.
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=o.id FOR UPDATE;
 SELECT greatest(c.release_not_before,dvnt_settlement.event_release_at(id)) INTO STRICT v_release_at FROM public.events WHERE id=o.event_id;
 SELECT s.release_at INTO existing_release FROM dvnt_settlement.orders s WHERE order_id=o.id;
 IF v_release_at IS NULL OR p_tax<0 OR p_gross IS DISTINCT FROM (c.snapshot->'order'->>'total_cents')::bigint+p_tax
  OR o.stripe_payment_intent_id IS DISTINCT FROM p_pi OR p_currency IS DISTINCT FROM c.snapshot->'order'->>'currency'
  OR c.last_error LIKE 'hold:%' OR o.status IN ('refunded','partially_refunded','disputed','canceled','cancelled','failed') THEN RAISE EXCEPTION 'source not eligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders WHERE order_id=o.id) THEN
  UPDATE public.orders SET status='paid',total_cents=p_gross,tax_cents=p_tax,paid_at=coalesce(paid_at,now()) WHERE id=o.id;
  -- Enrollment must invalidate old balances even when status was already paid.
  UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 END IF;
 PERFORM dvnt_settlement.enroll(o.id,p_charge,p_pi,p_currency,p_gross,coalesce(existing_release,v_release_at));
 UPDATE dvnt_settlement.orders SET release_at=greatest(dvnt_settlement.orders.release_at,v_release_at) WHERE order_id=o.id;
 UPDATE dvnt_settlement.checkouts SET source_verified_at=now(),last_error=NULL,outcome_unknown_since=NULL,
  next_check_at=NULL,retired_at=NULL,reconciliation_attempts=0 WHERE order_id=o.id;
 -- Source verification is not an override for refund/dispute/manual holds.
 UPDATE dvnt_settlement.orders SET blocked=false,block_reason='source_verified'
  WHERE order_id=o.id AND block_reason='awaiting_release_review'
    AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.holds WHERE order_id=o.id);
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE FUNCTION public.settlement_balance_checkpoint() RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('epoch',funding_epoch) FROM dvnt_settlement.controls WHERE singleton; $$;

CREATE FUNCTION public.settlement_reserve(p_allocation uuid,p_destination text,p_available bigint,p_balance_epoch bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a dvnt_settlement.allocations%ROWTYPE; o public.orders%ROWTYPE;
 e public.events%ROWTYPE; expected text; pending bigint; protected_commission bigint; risk_reserve bigint; result jsonb; c dvnt_settlement.checkouts%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM dvnt_settlement.allocations WHERE id=p_allocation;
 SELECT * INTO STRICT o FROM public.orders WHERE id=a.order_id FOR UPDATE;
 SELECT * INTO STRICT e FROM public.events WHERE id=o.event_id;
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=o.id;
 -- Global budget mutex serializes reservations against the caller's verified
 -- balance snapshot. Uncertain/reserved amounts remain fully reserved.
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 IF e.status IN ('cancelled','canceled') OR e.payout_status='disabled' OR EXISTS(SELECT 1 FROM dvnt_settlement.event_stops WHERE event_id=e.id AND reason<>'dispute_only')
 OR (e.payout_status='on_hold' AND NOT(c.organizer_user_id=ANY(ARRAY(SELECT unnest(owner_host_ids) FROM dvnt_settlement.controls WHERE singleton)) AND EXISTS(SELECT 1 FROM dvnt_settlement.event_stops WHERE event_id=e.id AND reason='dispute_only'))) THEN RAISE EXCEPTION 'event dispute or operational hold'; END IF;
 IF greatest(c.release_not_before,dvnt_settlement.event_release_at(e.id))>now() THEN RAISE EXCEPTION 'release window pending'; END IF;
 IF NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts WHERE order_id=o.id AND source_verified_at>now()-interval '60 seconds') THEN
  RAISE EXCEPTION 'source verification stale'; END IF;
 IF a.role='organizer' THEN SELECT stripe_account_id INTO expected FROM public.organizer_accounts WHERE host_id=a.recipient_id;
 ELSE SELECT coalesce(ep.stripe_account_id,oa.stripe_account_id) INTO expected FROM public.event_promoters ep
  LEFT JOIN public.organizer_accounts oa ON oa.host_id=a.recipient_user_id WHERE ep.id::text=a.recipient_id; END IF;
 IF expected IS NULL OR expected IS DISTINCT FROM p_destination THEN RAISE EXCEPTION 'recipient binding mismatch'; END IF;
 -- Held promoter liabilities remain reserved even without an account or
 -- after an error. In-flight/unknown sends are counted once, never twice.
 SELECT coalesce(sum(x.amount_cents),0) INTO pending FROM dvnt_settlement.allocations x
  JOIN dvnt_settlement.deliveries d ON d.allocation_id=x.id JOIN dvnt_settlement.orders s ON s.order_id=x.order_id
  WHERE d.state IN ('reserved','uncertain') AND s.currency=o.currency;
 SELECT coalesce(sum(x.amount_cents),0) INTO protected_commission FROM dvnt_settlement.allocations x
  JOIN dvnt_settlement.deliveries d ON d.allocation_id=x.id JOIN dvnt_settlement.orders s ON s.order_id=x.order_id
  WHERE x.role='promoter' AND x.id<>a.id AND d.state='held' AND s.currency=o.currency
    AND NOT dvnt_settlement.promoter_obligation_satisfied(x.id);
 -- A successful new-model payment can precede enrollment. Its frozen
 -- commission cannot be spent in that webhook/verification gap. Payment-pending
 -- checkout attempts do not pretend money exists. Legacy orders stay excluded.
 SELECT protected_commission+coalesce(sum((q.snapshot->'order'->>'promoter_commission_amount_cents')::bigint),0)
 INTO protected_commission FROM dvnt_settlement.checkouts q JOIN public.orders src ON src.id=q.order_id
 WHERE src.charge_model='separate_charges_and_transfers' AND src.status IN ('paid','partially_refunded','disputed')
  AND src.currency=o.currency AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders enrolled WHERE enrolled.order_id=src.id);
 SELECT reserve_cents INTO risk_reserve FROM dvnt_settlement.currency_reserves WHERE currency=o.currency;
 IF risk_reserve IS NULL THEN RAISE EXCEPTION 'platform risk reserve funding policy missing'; END IF;
 IF p_balance_epoch IS DISTINCT FROM (SELECT funding_epoch FROM dvnt_settlement.controls WHERE singleton)
  OR p_available IS NULL OR p_available<pending+protected_commission+risk_reserve+dvnt_settlement.unsettled_outflows(o.currency)+a.amount_cents THEN
  RAISE EXCEPTION 'insufficient unreserved funds';
 END IF;
 result:=dvnt_settlement.reserve(a.id,p_destination);
 UPDATE dvnt_settlement.deliveries SET last_error=NULL WHERE allocation_id=a.id;
 RETURN result || jsonb_build_object('order_id',o.id,'transfer_group','dvnt_settlement_'||o.id::text);
END $$;
CREATE FUNCTION public.settlement_hold(p_order_id uuid,p_event_id text,p_reason text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 PERFORM 1 FROM public.orders WHERE id=p_order_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM dvnt_settlement.orders WHERE order_id=p_order_id) THEN
  PERFORM dvnt_settlement.hold(p_order_id,p_event_id,p_reason);
 END IF;
 -- A pre-enrollment hold must persist as well, so verification cannot bypass it.
 IF p_reason IN ('refund','dispute','manual') THEN
  UPDATE dvnt_settlement.checkouts SET last_error='hold:'||p_reason WHERE order_id=p_order_id;
 ELSE RAISE EXCEPTION 'invalid hold'; END IF;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_uncertain(p_allocation uuid,p_error text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid;
BEGIN
 SELECT order_id INTO STRICT oid FROM dvnt_settlement.allocations WHERE id=p_allocation;
 PERFORM 1 FROM public.orders WHERE id=oid FOR UPDATE;
 UPDATE dvnt_settlement.deliveries SET state='uncertain' WHERE allocation_id=p_allocation AND state='reserved';
 UPDATE dvnt_settlement.checkouts SET last_error=left(p_error,200) WHERE order_id=oid;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_reconcile_transfer(p_allocation uuid,p_transfer text,p_destination text,p_charge text,p_currency text,p_amount bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 -- Lock the same budget mutex before recording completion. A completed
 -- transfer invalidates every previously observed available-balance snapshot.
 PERFORM 1 FROM public.orders WHERE id=(SELECT order_id FROM dvnt_settlement.allocations WHERE id=p_allocation) FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 PERFORM dvnt_settlement.reconcile_transfer(p_allocation,p_transfer,p_destination,p_charge,p_currency,p_amount);
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 UPDATE dvnt_settlement.deliveries SET completed_at=coalesce(completed_at,clock_timestamp()),last_error=NULL WHERE allocation_id=p_allocation;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE FUNCTION public.lookup_settlement_checkout(p_rail text,p_request_key text,p_user_id text,p_guest_email text)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('exists',EXISTS(SELECT 1 FROM dvnt_settlement.checkouts WHERE
 request_scope=p_rail||':'||coalesce(p_user_id,lower(p_guest_email))||':'||p_request_key));
$$;
REVOKE ALL ON FUNCTION public.lookup_settlement_checkout(text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.lookup_settlement_checkout(text,text,text,text) TO service_role;

CREATE FUNCTION dvnt_settlement.hold_on_money_state() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NEW.charge_model='separate_charges_and_transfers' AND NEW.status IS DISTINCT FROM OLD.status
 AND NEW.status IN ('refunded','partially_refunded','disputed','cancelled','canceled') THEN
  PERFORM public.settlement_hold(NEW.id,'order-state:'||NEW.status,
   CASE WHEN NEW.status='disputed' THEN 'dispute' ELSE 'refund' END);
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.hold_on_money_state() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER settlement_money_state_hold AFTER UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.hold_on_money_state();

-- A newly paid checkout changes the protected-liability set. Serialize its
-- commit with reservations, invalidating pre-commit available-balance reads.
CREATE FUNCTION dvnt_settlement.funding_liability_changed() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NEW.charge_model='separate_charges_and_transfers' AND NEW.status IS DISTINCT FROM OLD.status THEN
  UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.funding_liability_changed() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER settlement_funding_liability_change AFTER UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.funding_liability_changed();

CREATE FUNCTION public.settlement_legacy_event_eligible(p_event_id int) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('eligible',NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c
 JOIN public.orders o ON o.id=c.order_id WHERE o.event_id=p_event_id));
$$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA dvnt_settlement FROM service_role;

CREATE FUNCTION public.settlement_actor_summary(p_actor text,p_event_id int) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('verified',true,'rows',coalesce(jsonb_agg(to_jsonb(summary)),'[]'::jsonb)) FROM (
 SELECT s.currency,a.role AS recipient_role,
 CASE WHEN d.state IN ('uncertain','recovery_required') OR d.last_error IS NOT NULL THEN 'needs_review'
 WHEN d.state='held' THEN 'awaiting_settlement'
 WHEN d.state='reserved' THEN 'transfer_submitted'
 WHEN d.bank_payout_state='failed' THEN 'bank_failed'
 WHEN d.bank_payout_state='paid' THEN 'bank_paid'
 WHEN d.bank_payout_state='pending' THEN 'bank_pending'
 ELSE 'in_connected_balance' END AS stage,
 sum(a.amount_cents)::bigint AS amount_cents,count(*)::int AS allocation_count
 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.orders s ON s.order_id=a.order_id
 JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id JOIN public.orders o ON o.id=a.order_id
 WHERE o.event_id=p_event_id AND p_actor IS NOT NULL AND a.recipient_user_id=p_actor
 GROUP BY s.currency,a.role,stage
 ) summary;
$$;

CREATE FUNCTION public.settlement_processing_error(p_order_id uuid,p_code text,p_allocation uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_code NOT IN ('onboarding_required','recipient_restricted','funding_required','source_audit_limit','source_verification_stale','verification_required','hold_required','promoter_pending','platform_payout_policy_unverified') THEN RAISE EXCEPTION 'unknown processing reason'; END IF;
 IF p_allocation IS NULL THEN
  UPDATE dvnt_settlement.checkouts SET last_error=p_code WHERE order_id=p_order_id AND coalesce(last_error,'') NOT LIKE 'hold:%';
 ELSE
  UPDATE dvnt_settlement.deliveries SET last_error=p_code WHERE allocation_id=p_allocation
   AND EXISTS(SELECT 1 FROM dvnt_settlement.allocations a WHERE a.id=p_allocation AND a.order_id=p_order_id);
 END IF;
 RETURN jsonb_build_object('ok',true);
END $$;

-- No client JWT may read or invoke these internal financial operations.
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='public' AND (p.proname LIKE 'settlement_%' OR p.proname IN ('prepare_settlement_checkout','claim_settlement_checkout','finalize_settlement_checkout')) LOOP
  EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC,anon,authenticated';
  EXECUTE 'GRANT EXECUTE ON FUNCTION '||f.signature||' TO service_role';
 END LOOP;
END $$;
-- Runtime financial mutations must enter through the checked public wrappers.
-- Foundation-only low-level grants would bypass funding/source/refund gates.
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA dvnt_settlement FROM service_role;


-- SOURCE: docs/payments/drafts/settlement-release-policy.sql

-- No event is approved by this migration. Review policy, timezone and cohort
-- explicitly before writing a row. Seconds-based timing is not business days.
CREATE TABLE dvnt_settlement.release_policies (
 event_id int PRIMARY KEY REFERENCES public.events(id),
 policy text NOT NULL CHECK(policy='end_plus_five_business_days'),
 timezone text NOT NULL,
 review_reference text NOT NULL CHECK(length(trim(review_reference)) BETWEEN 8 AND 300)
);
ALTER TABLE dvnt_settlement.release_policies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.release_policies FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION dvnt_settlement.event_release_at(p_event int) RETURNS timestamptz
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE p dvnt_settlement.release_policies%ROWTYPE; e public.events%ROWTYPE;
 canonical_end timestamptz; local_end timestamp; n int:=0; result timestamptz;
BEGIN
 SELECT * INTO p FROM dvnt_settlement.release_policies WHERE event_id=p_event;
 IF NOT FOUND THEN RAISE EXCEPTION 'release policy not configured for event'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=p.timezone) THEN RAISE EXCEPTION 'release timezone not reviewed'; END IF;
 SELECT * INTO STRICT e FROM public.events WHERE id=p_event;
 canonical_end:=coalesce(e.end_date::timestamptz,e.start_date::timestamptz+interval '6 hours');
 IF canonical_end IS NULL OR NOT isfinite(canonical_end) THEN RAISE EXCEPTION 'event end missing'; END IF;
 local_end:=canonical_end AT TIME ZONE p.timezone;
 WHILE n<5 LOOP
  local_end:=local_end+interval '1 day';
  IF extract(isodow FROM local_end)<6 THEN n:=n+1; END IF;
 END LOOP;
 result:=local_end AT TIME ZONE p.timezone;
 IF e.payout_release_at IS NOT NULL AND NOT isfinite(e.payout_release_at) THEN RAISE EXCEPTION 'release date invalid'; END IF;
 RETURN greatest(result,e.payout_release_at);
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.event_release_at(int) FROM PUBLIC,anon,authenticated,service_role;


-- SOURCE: docs/payments/drafts/settlement-checkout-cutover.sql
-- Permanent per-event routing fence. Installation does NOT cut over events
-- without an approved release/cohort policy or an existing separate charge.

CREATE TABLE dvnt_settlement.checkout_cutovers (
 event_id int PRIMARY KEY REFERENCES public.events(id),
 review_reference text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE dvnt_settlement.checkout_cutovers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.checkout_cutovers FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION dvnt_settlement.freeze_checkout_cutover() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'checkout cutover is permanent'; END $$;
CREATE TRIGGER immutable_checkout_cutover BEFORE UPDATE OR DELETE ON dvnt_settlement.checkout_cutovers
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.freeze_checkout_cutover();
CREATE TRIGGER no_truncate_checkout_cutover BEFORE TRUNCATE ON dvnt_settlement.checkout_cutovers
 FOR EACH STATEMENT EXECUTE FUNCTION dvnt_settlement.freeze_checkout_cutover();
CREATE FUNCTION dvnt_settlement.record_checkout_cutover() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO dvnt_settlement.checkout_cutovers(event_id,review_reference) VALUES(NEW.event_id,NEW.review_reference)
  ON CONFLICT(event_id) DO NOTHING;
 RETURN NEW;
END $$;
CREATE TRIGGER mark_checkout_cohort_cutover AFTER INSERT OR UPDATE ON dvnt_settlement.release_policies
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.record_checkout_cutover();
INSERT INTO dvnt_settlement.checkout_cutovers(event_id,review_reference)
 SELECT event_id,review_reference FROM dvnt_settlement.release_policies ON CONFLICT DO NOTHING;
INSERT INTO dvnt_settlement.checkout_cutovers(event_id,review_reference)
 SELECT DISTINCT event_id,'pre-existing separate-charge history' FROM public.orders
 WHERE charge_model='separate_charges_and_transfers' AND event_id IS NOT NULL ON CONFLICT DO NOTHING;

CREATE FUNCTION public.settlement_checkout_route(p_event_id int) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_event_id IS NULL OR p_event_id<=0 OR NOT EXISTS(SELECT 1 FROM public.events WHERE id=p_event_id)
 THEN RAISE EXCEPTION 'checkout route unavailable'; END IF;
 -- A read cannot fence an already-running legacy provider request. Operators
 -- must quiesce and drain this event BEFORE changing its reviewed cohort.
 -- Once cut over, removing a policy or turning flags off never restores legacy.
 RETURN jsonb_build_object('ok',true,'charge_model',CASE WHEN
  EXISTS(SELECT 1 FROM dvnt_settlement.checkout_cutovers WHERE event_id=p_event_id)
  OR EXISTS(SELECT 1 FROM dvnt_settlement.release_policies WHERE event_id=p_event_id)
  OR EXISTS(SELECT 1 FROM public.orders WHERE event_id=p_event_id AND charge_model='separate_charges_and_transfers')
  THEN 'separate_charges_and_transfers' ELSE 'destination_charge' END);
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.freeze_checkout_cutover(),dvnt_settlement.record_checkout_cutover() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.settlement_checkout_route(int) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.settlement_checkout_route(int) TO service_role;


-- SOURCE: docs/payments/drafts/settlement-recovery.sql
-- DRAFT ONLY. Private recovery/bank extension; execution disabled by default.

ALTER TABLE dvnt_settlement.controls ADD COLUMN recovery_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE dvnt_settlement.refunds (
 refund_id text PRIMARY KEY CHECK(refund_id ~ '^re_[A-Za-z0-9_]+$'),order_id uuid NOT NULL REFERENCES public.orders(id),
 charge_id text NOT NULL,currency text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>0),
 full_refund boolean NOT NULL,eligible_cents bigint,basis_cents bigint,unit_key text,
 state text NOT NULL CHECK(state IN('quarantined','allocated')),created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(eligible_cents IS NULL OR eligible_cents BETWEEN 0 AND amount_cents),
 CHECK(basis_cents IS NULL OR basis_cents>0),UNIQUE(order_id,unit_key)
);
CREATE TABLE dvnt_settlement.recoveries (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),refund_id text NOT NULL REFERENCES dvnt_settlement.refunds(refund_id),
 allocation_id uuid NOT NULL REFERENCES dvnt_settlement.allocations(id),amount_cents bigint NOT NULL CHECK(amount_cents>0),
 state text NOT NULL DEFAULT 'open' CHECK(state IN('open','attempted','uncertain','recovered')),
 transfer_id text,last_error text, idempotency_key text NOT NULL UNIQUE,reversal_id text UNIQUE,attempted_at timestamptz,completed_at timestamptz,
 UNIQUE(refund_id,allocation_id),
 CHECK(state<>'recovered' OR (reversal_id IS NOT NULL AND reversal_id ~ '^trr_[A-Za-z0-9_]+$' AND completed_at IS NOT NULL))
);
CREATE TABLE dvnt_settlement.bank_events (
 event_id text PRIMARY KEY,account text NOT NULL,payout_id text NOT NULL,event_created bigint NOT NULL,
 state text NOT NULL CHECK(state IN('paid','failed','reconcile')),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE dvnt_settlement.bank_proofs (
 allocation_id uuid PRIMARY KEY REFERENCES dvnt_settlement.allocations(id),account text NOT NULL,
 transfer_id text NOT NULL,destination_payment text NOT NULL,transaction_id text NOT NULL UNIQUE,
 payout_id text NOT NULL,proof jsonb NOT NULL,state text NOT NULL CHECK(state IN('paid','pending','failed')),
 event_created bigint NOT NULL,verified_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE dvnt_settlement.refunds ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.recoveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.bank_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.bank_proofs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.refunds,dvnt_settlement.recoveries,dvnt_settlement.bank_events,dvnt_settlement.bank_proofs FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.settlement_record_refund(p_order_id uuid,p_refund_id text,p_charge_id text,p_amount bigint,p_currency text,
 p_full boolean,p_eligible bigint DEFAULT NULL,p_basis bigint DEFAULT NULL,p_unit_key text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE;c dvnt_settlement.checkouts%ROWTYPE;old dvnt_settlement.refunds%ROWTYPE;
 a record; eligible bigint; prior bigint; target bigint; delta bigint; valid boolean;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 SELECT * INTO STRICT c FROM dvnt_settlement.checkouts WHERE order_id=p_order_id FOR UPDATE;
 IF o.charge_model IS DISTINCT FROM 'separate_charges_and_transfers' OR p_amount<=0 OR p_amount>o.total_cents
 OR p_currency IS DISTINCT FROM o.currency OR p_refund_id !~ '^re_[A-Za-z0-9_]+$' OR p_charge_id !~ '^ch_[A-Za-z0-9_]+$'
 OR EXISTS(SELECT 1 FROM dvnt_settlement.orders WHERE order_id=o.id AND charge_id IS DISTINCT FROM p_charge_id)
 THEN RAISE EXCEPTION 'refund source mismatch'; END IF;
 PERFORM public.settlement_hold(o.id,p_refund_id,'refund');
 SELECT * INTO old FROM dvnt_settlement.refunds WHERE refund_id=p_refund_id;
 IF FOUND THEN
  IF old.order_id IS DISTINCT FROM o.id OR old.charge_id IS DISTINCT FROM p_charge_id OR old.currency IS DISTINCT FROM p_currency
   OR old.amount_cents IS DISTINCT FROM p_amount THEN RAISE EXCEPTION 'refund replay mismatch'; END IF;
  IF old.state='allocated' THEN RETURN jsonb_build_object('ok',true,'duplicate',true); END IF;
  -- A later verified full refund can close previously unknown partial exposure.
  IF NOT p_full THEN RETURN jsonb_build_object('ok',true,'quarantined',true); END IF;
 END IF;
 valid:=p_full OR (c.snapshot->'selection'->>'ticket_type_id' IS NOT NULL AND
  p_basis=(c.snapshot->'order'->>'subtotal_cents')::bigint AND p_basis>0 AND p_eligible>=0 AND p_eligible<=p_amount AND
  p_eligible<=p_basis AND p_unit_key LIKE 'ticket:%');
 IF NOT p_full AND EXISTS(SELECT 1 FROM dvnt_settlement.refunds WHERE order_id=o.id AND unit_key=p_unit_key AND refund_id<>p_refund_id) THEN valid:=false; END IF;
 INSERT INTO dvnt_settlement.refunds(refund_id,order_id,charge_id,currency,amount_cents,full_refund,eligible_cents,basis_cents,unit_key,state)
 VALUES(p_refund_id,o.id,p_charge_id,p_currency,p_amount,p_full,CASE WHEN valid AND NOT p_full THEN p_eligible END,
  CASE WHEN valid AND NOT p_full THEN p_basis END,CASE WHEN valid AND NOT p_full THEN p_unit_key END,
  CASE WHEN valid THEN 'allocated' ELSE 'quarantined' END)
 ON CONFLICT(refund_id) DO UPDATE SET full_refund=true,state='allocated',eligible_cents=NULL,basis_cents=NULL,unit_key=NULL;
 IF NOT coalesce(valid,false) THEN RETURN jsonb_build_object('ok',true,'quarantined',true); END IF;
 SELECT coalesce(sum(eligible_cents),0) INTO eligible FROM dvnt_settlement.refunds WHERE order_id=o.id AND state='allocated';
 IF NOT p_full AND eligible>p_basis THEN RAISE EXCEPTION 'refunded eligible amount exceeds frozen allocation'; END IF;
 FOR a IN SELECT * FROM dvnt_settlement.allocations WHERE order_id=o.id ORDER BY id LOOP
  SELECT coalesce(sum(amount_cents),0) INTO prior FROM dvnt_settlement.recoveries WHERE allocation_id=a.id;
  target:=CASE WHEN p_full THEN a.amount_cents ELSE floor(a.amount_cents::numeric*eligible/p_basis)::bigint END;
  delta:=greatest(0,target-prior);
  IF prior+delta>a.amount_cents THEN RAISE EXCEPTION 'recovery exceeds allocation'; END IF;
  IF delta>0 THEN INSERT INTO dvnt_settlement.recoveries(refund_id,allocation_id,amount_cents,idempotency_key)
   VALUES(p_refund_id,a.id,delta,'dvnt:recovery:v1:'||a.id::text||':'||p_refund_id); END IF;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'quarantined',false);
END $$;

CREATE FUNCTION public.settlement_recovery(p_recovery_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT to_jsonb(r)||jsonb_build_object('transfer_id',coalesce(r.transfer_id,d.stripe_transfer_id))
 FROM dvnt_settlement.recoveries r JOIN dvnt_settlement.deliveries d ON d.allocation_id=r.allocation_id WHERE r.id=p_recovery_id;
$$;
CREATE FUNCTION public.settlement_claim_recovery(p_recovery_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r dvnt_settlement.recoveries%ROWTYPE;d dvnt_settlement.deliveries%ROWTYPE;oid uuid;
BEGIN
 SELECT a.order_id INTO STRICT oid FROM dvnt_settlement.recoveries x JOIN dvnt_settlement.allocations a ON a.id=x.allocation_id WHERE x.id=p_recovery_id;
 PERFORM 1 FROM public.orders WHERE id=oid FOR UPDATE;
 SELECT * INTO STRICT r FROM dvnt_settlement.recoveries WHERE id=p_recovery_id FOR UPDATE;
 IF NOT (SELECT recovery_enabled FROM dvnt_settlement.controls WHERE singleton) THEN RAISE EXCEPTION 'recovery disabled'; END IF;
 IF r.state<>'open' THEN RETURN jsonb_build_object('ok',true,'claimed',false); END IF;
 SELECT * INTO STRICT d FROM dvnt_settlement.deliveries WHERE allocation_id=r.allocation_id FOR UPDATE;
 IF d.stripe_transfer_id IS NULL OR d.state NOT IN('transferred','recovery_required') THEN RAISE EXCEPTION 'outgoing transfer outcome not proven'; END IF;
 UPDATE dvnt_settlement.recoveries SET state='attempted',attempted_at=now(),transfer_id=d.stripe_transfer_id WHERE id=r.id;
 RETURN public.settlement_recovery(r.id)||jsonb_build_object('ok',true,'claimed',true);
END $$;
CREATE FUNCTION public.settlement_uncertain_recovery(p_recovery_id uuid,p_error text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 UPDATE dvnt_settlement.recoveries SET state='uncertain',last_error=left(p_error,500) WHERE id=p_recovery_id AND state='attempted';
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_finish_recovery(p_recovery_id uuid,p_reversal_id text,p_amount bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r dvnt_settlement.recoveries%ROWTYPE;
BEGIN
 SELECT * INTO STRICT r FROM dvnt_settlement.recoveries WHERE id=p_recovery_id FOR UPDATE;
 IF p_amount IS DISTINCT FROM r.amount_cents OR p_reversal_id IS NULL OR p_reversal_id !~ '^trr_[A-Za-z0-9_]+$' OR r.transfer_id IS NULL OR
 r.state NOT IN('attempted','uncertain','recovered') OR (r.reversal_id IS NOT NULL AND r.reversal_id IS DISTINCT FROM p_reversal_id)
 THEN RAISE EXCEPTION 'recovery result mismatch'; END IF;
 UPDATE dvnt_settlement.recoveries SET state='recovered',reversal_id=p_reversal_id,completed_at=coalesce(completed_at,now()) WHERE id=r.id;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE FUNCTION public.settlement_bank_event(p_account text,p_payout text,p_event_id text,p_created bigint,p_state text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE old dvnt_settlement.bank_events%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dvnt:bank:'||p_account,0));
 IF p_account !~ '^acct_[A-Za-z0-9_]+$' OR p_payout !~ '^po_[A-Za-z0-9_]+$' OR p_created<0 OR p_state NOT IN('paid','failed','reconcile') OR length(p_event_id)=0
 THEN RAISE EXCEPTION 'invalid bank event'; END IF;
 SELECT * INTO old FROM dvnt_settlement.bank_events WHERE event_id=p_event_id;
 IF FOUND AND ROW(old.account,old.payout_id,old.event_created,old.state) IS DISTINCT FROM ROW(p_account,p_payout,p_created,p_state)
 THEN RAISE EXCEPTION 'bank event replay mismatch'; END IF;
 INSERT INTO dvnt_settlement.bank_events(event_id,account,payout_id,event_created,state)
 VALUES(p_event_id,p_account,p_payout,p_created,p_state) ON CONFLICT DO NOTHING;
 -- A payout.paid event alone never proves that an allocation reached a bank.
 IF p_state='failed' THEN
  UPDATE dvnt_settlement.bank_proofs SET state='failed',event_created=p_created
   WHERE account=p_account AND payout_id=p_payout AND event_created<=p_created;
  UPDATE dvnt_settlement.deliveries d SET bank_payout_state='failed' FROM dvnt_settlement.bank_proofs b
   WHERE b.allocation_id=d.allocation_id AND b.account=p_account AND b.payout_id=p_payout AND b.state='failed';
 END IF;
 UPDATE dvnt_settlement.recovery_scans s SET not_before=now() WHERE s.kind='bank' AND s.work_key LIKE '%:'||p_payout;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_bank_proof(p_allocation uuid,p_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE d dvnt_settlement.deliveries%ROWTYPE;b dvnt_settlement.bank_proofs%ROWTYPE;failed_at bigint;stamp bigint;v_state text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dvnt:bank:'||(p_proof->>'account'),0));
 SELECT * INTO STRICT d FROM dvnt_settlement.deliveries WHERE allocation_id=p_allocation FOR UPDATE;
 IF d.stripe_transfer_id IS DISTINCT FROM p_proof->>'transferId' OR d.destination IS DISTINCT FROM p_proof->>'account'
 OR d.state NOT IN('transferred','recovery_required') OR p_proof->>'destinationPayment' !~ '^py_[A-Za-z0-9_]+$'
 OR p_proof->>'transactionId' !~ '^txn_[A-Za-z0-9_]+$' OR p_proof->>'payoutId' !~ '^po_[A-Za-z0-9_]+$'
 OR (p_proof->>'grossCents')::bigint IS DISTINCT FROM (SELECT amount_cents FROM dvnt_settlement.allocations WHERE id=p_allocation)
 OR p_proof->>'netContributionCents' IS NULL OR (p_proof->>'netContributionCents')::bigint<1 OR (p_proof->>'netContributionCents')::bigint>(p_proof->>'grossCents')::bigint
 OR p_proof->>'currency' IS DISTINCT FROM (SELECT o.currency FROM dvnt_settlement.orders o JOIN dvnt_settlement.allocations a ON a.order_id=o.order_id WHERE a.id=p_allocation)
 OR p_proof->>'status' NOT IN('paid','pending','failed') OR (p_proof->>'created')::bigint<0
 THEN RAISE EXCEPTION 'bank proof linkage mismatch'; END IF;
 stamp:=(p_proof->>'created')::bigint;v_state:=p_proof->>'status';
 SELECT max(event_created) INTO failed_at FROM dvnt_settlement.bank_events
  WHERE account=d.destination AND payout_id=p_proof->>'payoutId' AND state='failed';
 IF failed_at IS NOT NULL THEN v_state:='failed';stamp:=greatest(stamp,failed_at); END IF;
 SELECT * INTO b FROM dvnt_settlement.bank_proofs WHERE allocation_id=p_allocation;
 IF FOUND THEN
  IF b.account IS DISTINCT FROM d.destination OR b.transfer_id IS DISTINCT FROM d.stripe_transfer_id OR
   b.destination_payment IS DISTINCT FROM p_proof->>'destinationPayment' OR b.transaction_id IS DISTINCT FROM p_proof->>'transactionId'
   THEN RAISE EXCEPTION 'bank proof source changed'; END IF;
  IF b.event_created>stamp OR (b.payout_id=p_proof->>'payoutId' AND b.state='failed') THEN
   RETURN jsonb_build_object('ok',true,'state',b.state,'stale',true); END IF;
 END IF;
 INSERT INTO dvnt_settlement.bank_proofs(allocation_id,account,transfer_id,destination_payment,transaction_id,payout_id,proof,state,event_created)
 VALUES(p_allocation,d.destination,d.stripe_transfer_id,p_proof->>'destinationPayment',p_proof->>'transactionId',p_proof->>'payoutId',p_proof,v_state,stamp)
 ON CONFLICT(allocation_id) DO UPDATE SET payout_id=excluded.payout_id,proof=excluded.proof,state=excluded.state,event_created=excluded.event_created,verified_at=now();
 UPDATE dvnt_settlement.deliveries SET bank_payout_state=v_state WHERE allocation_id=p_allocation;
 RETURN jsonb_build_object('ok',true,'state',v_state);
END $$;
-- Durable fair queues lease a page before returning it. A bad first page can
-- never permanently hide later work. Expired leases retry after a worker crash.
CREATE TABLE dvnt_settlement.recovery_scans (
 kind text NOT NULL CHECK(kind IN('bank','refund','recovery')),work_key text NOT NULL,
 not_before timestamptz NOT NULL,last_checked timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(kind,work_key)
);
ALTER TABLE dvnt_settlement.recovery_scans ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.recovery_scans FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.settlement_recovery_wake(p_order_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 UPDATE dvnt_settlement.recovery_scans SET not_before=now() WHERE kind='refund' AND work_key=p_order_id::text;
 RETURN jsonb_build_object('ok',true);
END $$;
-- bank_payout_state=paid means proven inclusion in a paid automatic batch,
-- not an assertion that the allocation gross was deposited without fees.
CREATE FUNCTION public.settlement_bank_candidates(p_limit int DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;work record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dvnt:bank_scan',0));
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO result FROM (
 SELECT a.id,a.order_id,a.amount_cents,d.destination,d.stripe_transfer_id,o.currency,e.payout_id
 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
 JOIN dvnt_settlement.orders o ON o.order_id=a.order_id
 JOIN (SELECT account,payout_id,max(event_created) AS newest FROM dvnt_settlement.bank_events GROUP BY account,payout_id) e ON e.account=d.destination
 LEFT JOIN dvnt_settlement.recovery_scans scan ON scan.kind='bank' AND scan.work_key=a.id::text||':'||e.payout_id
 WHERE d.state IN('transferred','recovery_required') AND d.stripe_transfer_id IS NOT NULL
 AND (scan.not_before IS NULL OR scan.not_before<=now())
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.bank_proofs b WHERE b.allocation_id=a.id AND (b.state='paid' OR (b.payout_id=e.payout_id AND b.state='failed')))
 ORDER BY scan.last_checked NULLS FIRST,a.id,e.payout_id LIMIT greatest(1,least(p_limit,1000))
 ) x;
 FOR work IN SELECT value FROM jsonb_array_elements(result) LOOP
  INSERT INTO dvnt_settlement.recovery_scans(kind,work_key,not_before) VALUES('bank',(work.value->>'id')||':'||(work.value->>'payout_id'),now()+interval '5 minutes')
  ON CONFLICT(kind,work_key) DO UPDATE SET not_before=excluded.not_before,last_checked=now();
 END LOOP;
 RETURN result;
END $$;
CREATE FUNCTION public.settlement_refund_candidates(p_limit int DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;work record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dvnt:refund_scan',0));
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO result FROM (
 SELECT o.id AS order_id FROM public.orders o JOIN dvnt_settlement.checkouts c ON c.order_id=o.id
 LEFT JOIN dvnt_settlement.recovery_scans scan ON scan.kind='refund' AND scan.work_key=o.id::text
 WHERE o.charge_model='separate_charges_and_transfers' AND o.stripe_payment_intent_id IS NOT NULL
 AND (o.status IN('refunded','partially_refunded') OR c.last_error='hold:refund')
 AND (scan.not_before IS NULL OR scan.not_before<=now())
 ORDER BY scan.last_checked NULLS FIRST,c.created_at LIMIT greatest(1,least(p_limit,1000))
 ) x;
 FOR work IN SELECT value FROM jsonb_array_elements(result) LOOP
  INSERT INTO dvnt_settlement.recovery_scans(kind,work_key,not_before) VALUES('refund',work.value->>'order_id',now()+interval '5 minutes')
  ON CONFLICT(kind,work_key) DO UPDATE SET not_before=excluded.not_before,last_checked=now();
 END LOOP;
 RETURN result;
END $$;
CREATE FUNCTION public.settlement_recovery_candidates(p_limit int DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;work record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dvnt:recovery_scan',0));
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO result FROM (
 SELECT r.id,r.state FROM dvnt_settlement.recoveries r JOIN dvnt_settlement.deliveries d ON d.allocation_id=r.allocation_id
 LEFT JOIN dvnt_settlement.recovery_scans scan ON scan.kind='recovery' AND scan.work_key=r.id::text
 WHERE r.state IN('open','attempted','uncertain') AND d.stripe_transfer_id IS NOT NULL
 AND (scan.not_before IS NULL OR scan.not_before<=now())
 ORDER BY scan.last_checked NULLS FIRST,r.id LIMIT greatest(1,least(p_limit,1000))
 ) x;
 FOR work IN SELECT value FROM jsonb_array_elements(result) LOOP
  INSERT INTO dvnt_settlement.recovery_scans(kind,work_key,not_before) VALUES('recovery',work.value->>'id',now()+interval '5 minutes')
  ON CONFLICT(kind,work_key) DO UPDATE SET not_before=excluded.not_before,last_checked=now();
 END LOOP;
 RETURN result;
END $$;
DO $$ DECLARE f record;BEGIN
 FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'
 AND p.proname IN('settlement_record_refund','settlement_recovery','settlement_claim_recovery','settlement_uncertain_recovery',
 'settlement_recovery_wake','settlement_finish_recovery','settlement_bank_event','settlement_bank_proof','settlement_bank_candidates','settlement_refund_candidates','settlement_recovery_candidates') LOOP
 EXECUTE 'REVOKE ALL ON FUNCTION '||f.sig||' FROM PUBLIC,anon,authenticated';
 EXECUTE 'GRANT EXECUTE ON FUNCTION '||f.sig||' TO service_role';END LOOP;
END $$;


-- SOURCE: docs/payments/drafts/settlement-outflows.sql

-- Every local new-ledger refund is claimed before provider I/O. Unknown outcomes
-- retain their maximum debit; only exact provider evidence releases the budget.
CREATE TABLE dvnt_settlement.refund_outflows (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id),
 request_key text NOT NULL,request_body jsonb NOT NULL,currency text NOT NULL,unit_key text,
 amount_cents bigint NOT NULL CHECK(amount_cents>0),request_amount bigint,
 state text NOT NULL DEFAULT 'attempted' CHECK(state IN('attempted','uncertain','submitted','settled','canceled')),
 refund_id text UNIQUE,proof jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,
 UNIQUE(order_id,request_key),UNIQUE(order_id,unit_key)
);
CREATE TABLE dvnt_settlement.dispute_outflows (
 order_id uuid PRIMARY KEY REFERENCES public.orders(id),currency text NOT NULL,
 amount_cents bigint NOT NULL CHECK(amount_cents>0),state text NOT NULL DEFAULT 'manual_review' CHECK(state='manual_review'),
 created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE dvnt_settlement.refund_outflows ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.dispute_outflows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.refund_outflows,dvnt_settlement.dispute_outflows FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION dvnt_settlement.unsettled_outflows(p_currency text) RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce((SELECT sum(amount_cents) FROM dvnt_settlement.refund_outflows WHERE currency=p_currency AND state IN('attempted','uncertain','submitted')),0)
 +coalesce((SELECT sum(amount_cents) FROM dvnt_settlement.dispute_outflows WHERE currency=p_currency),0);
$$;
REVOKE ALL ON FUNCTION dvnt_settlement.unsettled_outflows(text) FROM PUBLIC,anon,authenticated,service_role;

ALTER FUNCTION public.settlement_hold(uuid,text,text) RENAME TO settlement_hold_without_outflows;
REVOKE ALL ON FUNCTION public.settlement_hold_without_outflows(uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.settlement_hold(p_order_id uuid,p_event_id text,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 PERFORM public.settlement_hold_without_outflows(p_order_id,p_event_id,p_reason);
 IF p_reason='dispute' THEN
  INSERT INTO dvnt_settlement.dispute_outflows(order_id,currency,amount_cents) VALUES(o.id,o.currency,o.total_cents)
   ON CONFLICT(order_id) DO NOTHING;
 END IF;
 -- Also invalidate balances observed before an externally reported refund/hold.
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE FUNCTION public.settlement_refund_outflow_begin(p_order_id uuid,p_request_key text,p_body jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders%ROWTYPE; intent dvnt_settlement.refund_outflows%ROWTYPE; amount bigint;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 IF o.charge_model IS DISTINCT FROM 'separate_charges_and_transfers' OR p_body->>'payment_intent' IS DISTINCT FROM o.stripe_payment_intent_id
 OR p_request_key IS NULL OR length(p_request_key) NOT BETWEEN 8 AND 200 OR jsonb_typeof(p_body)<>'object'
 OR o.currency IS NULL OR o.total_cents IS NULL OR o.total_cents<=0 THEN RAISE EXCEPTION 'invalid refund debit intent'; END IF;
 IF p_body ? 'amount' THEN
  IF p_body->>'amount' !~ '^[0-9]+$' THEN RAISE EXCEPTION 'invalid refund amount'; END IF;
  amount:=(p_body->>'amount')::bigint;
  IF amount<=0 OR amount>o.total_cents THEN RAISE EXCEPTION 'invalid refund amount'; END IF;
 END IF;
 SELECT * INTO intent FROM dvnt_settlement.refund_outflows WHERE order_id=o.id AND request_key=p_request_key;
 IF FOUND THEN
  IF intent.request_body IS DISTINCT FROM p_body THEN RAISE EXCEPTION 'refund debit replay mismatch'; END IF;
  RETURN jsonb_build_object('ok',true,'claimed',false,'id',intent.id,'state',intent.state);
 END IF;
 -- Different keys cannot bypass an ambiguous whole-order/partial attempt.
 IF EXISTS(SELECT 1 FROM dvnt_settlement.refund_outflows WHERE order_id=o.id AND state IN('attempted','uncertain','submitted'))
 THEN RAISE EXCEPTION 'refund debit requires reconciliation'; END IF;
 PERFORM public.settlement_hold(o.id,'refund_request:'||p_request_key,'refund');
 INSERT INTO dvnt_settlement.refund_outflows(order_id,request_key,request_body,currency,amount_cents,request_amount,unit_key)
 VALUES(o.id,p_request_key,p_body,o.currency,coalesce(amount,o.total_cents),amount,
 CASE WHEN amount IS NULL THEN 'whole_order'
 WHEN p_body->>'metadata[ticket_id]' IS NOT NULL THEN 'ticket:'||(p_body->>'metadata[ticket_id]')
 WHEN p_body->>'metadata[cart_line_item_id]' IS NOT NULL THEN 'cart_line:'||(p_body->>'metadata[cart_line_item_id]') END) RETURNING * INTO intent;
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN jsonb_build_object('ok',true,'claimed',true,'id',intent.id,'state',intent.state);
END $$;
CREATE FUNCTION public.settlement_refund_outflow_observe(p_intent uuid,p_refund_id text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid; intent dvnt_settlement.refund_outflows%ROWTYPE;
BEGIN
 SELECT order_id INTO STRICT oid FROM dvnt_settlement.refund_outflows WHERE id=p_intent;
 PERFORM 1 FROM public.orders WHERE id=oid FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT intent FROM dvnt_settlement.refund_outflows WHERE id=p_intent FOR UPDATE;
 IF p_refund_id IS NOT NULL AND (p_refund_id !~ '^re_[A-Za-z0-9_]+$' OR intent.refund_id IS NOT NULL AND intent.refund_id<>p_refund_id)
 THEN RAISE EXCEPTION 'refund debit response mismatch'; END IF;
 IF intent.state IN('settled','canceled') THEN RETURN jsonb_build_object('ok',true); END IF;
 UPDATE dvnt_settlement.refund_outflows SET state=CASE WHEN p_refund_id IS NULL THEN 'uncertain' ELSE 'submitted' END,
 refund_id=coalesce(p_refund_id,refund_id) WHERE id=p_intent;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_refund_outflow_reconcile(p_intent uuid,p_proof jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid; intent dvnt_settlement.refund_outflows%ROWTYPE; o public.orders%ROWTYPE; target text; amount bigint;
BEGIN
 SELECT order_id INTO STRICT oid FROM dvnt_settlement.refund_outflows WHERE id=p_intent;
 SELECT * INTO STRICT o FROM public.orders WHERE id=oid FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT intent FROM dvnt_settlement.refund_outflows WHERE id=p_intent FOR UPDATE;
 amount:=(p_proof->>'amount')::bigint;
 IF p_proof->>'intent_id' IS DISTINCT FROM intent.id::text OR p_proof->>'order_id' IS DISTINCT FROM oid::text
 OR p_proof->>'payment_intent' IS DISTINCT FROM o.stripe_payment_intent_id OR p_proof->>'currency' IS DISTINCT FROM intent.currency
 OR p_proof->>'refund_id' IS NULL OR p_proof->>'refund_id' !~ '^re_[A-Za-z0-9_]+$'
 OR (intent.refund_id IS NOT NULL AND intent.refund_id IS DISTINCT FROM p_proof->>'refund_id')
 OR amount IS NULL OR amount<=0 OR amount>intent.amount_cents OR (intent.request_amount IS NOT NULL AND amount<>intent.request_amount)
 THEN RAISE EXCEPTION 'refund debit evidence mismatch'; END IF;
 IF p_proof->>'status'='succeeded' THEN
  IF p_proof->>'transaction_id' IS NULL OR p_proof->>'transaction_id' !~ '^txn_[A-Za-z0-9_]+$'
   OR p_proof->>'transaction_source' IS DISTINCT FROM p_proof->>'refund_id'
   OR p_proof->>'transaction_currency' IS DISTINCT FROM intent.currency
   OR (p_proof->>'transaction_amount')::bigint IS DISTINCT FROM -amount
   OR p_proof->>'transaction_status' IS DISTINCT FROM 'available'
   OR p_proof->>'transaction_type' IS DISTINCT FROM 'refund' THEN RAISE EXCEPTION 'refund debit balance proof missing'; END IF;
  target:='settled';
 ELSIF p_proof->>'status' IN('failed','canceled') THEN
  -- If a failed refund has any debit transaction, funds returning to available
  -- must be proven separately. Keep it reserved for manual review instead.
  IF NOT(p_proof ? 'transaction_id') OR NOT(p_proof ? 'failure_transaction_id')
   OR p_proof->>'transaction_id' IS NOT NULL OR p_proof->>'failure_transaction_id' IS NOT NULL
   THEN RAISE EXCEPTION 'failed refund balance requires review'; END IF;
  target:='canceled';
 ELSE RAISE EXCEPTION 'refund debit remains pending'; END IF;
 IF intent.state IN('settled','canceled') THEN
  IF intent.state<>target OR intent.proof IS DISTINCT FROM p_proof THEN RAISE EXCEPTION 'refund debit terminal evidence mismatch'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicate',true);
 END IF;
 UPDATE dvnt_settlement.refund_outflows SET state=target,refund_id=p_proof->>'refund_id',proof=p_proof,completed_at=now() WHERE id=p_intent;
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN jsonb_build_object('ok',true,'state',target);
END $$;
REVOKE ALL ON FUNCTION public.settlement_hold(uuid,text,text),public.settlement_refund_outflow_begin(uuid,text,jsonb),public.settlement_refund_outflow_observe(uuid,text),public.settlement_refund_outflow_reconcile(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_hold(uuid,text,text),public.settlement_refund_outflow_begin(uuid,text,jsonb),public.settlement_refund_outflow_observe(uuid,text),public.settlement_refund_outflow_reconcile(uuid,jsonb) TO service_role;


-- SOURCE: docs/payments/drafts/settlement-observability.sql

ALTER TABLE dvnt_settlement.controls ADD COLUMN last_worker_started_at timestamptz,
 ADD COLUMN last_worker_completed_at timestamptz, ADD COLUMN last_worker_error_at timestamptz,
 ADD COLUMN last_worker_summary jsonb,
 ADD COLUMN platform_payout_policy_verified boolean, ADD COLUMN platform_payout_policy_checked_at timestamptz;
CREATE FUNCTION public.settlement_worker_observation(p_phase text,p_summary jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_phase NOT IN ('started','completed','error') THEN RAISE EXCEPTION 'unknown worker phase'; END IF;
 UPDATE dvnt_settlement.controls SET
 last_worker_started_at=CASE WHEN p_phase='started' THEN clock_timestamp() ELSE last_worker_started_at END,
 last_worker_completed_at=CASE WHEN p_phase='completed' THEN clock_timestamp() ELSE last_worker_completed_at END,
 last_worker_error_at=CASE WHEN p_phase='error' THEN clock_timestamp() ELSE last_worker_error_at END,
 last_worker_summary=p_summary WHERE singleton;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.settlement_platform_policy_observation(p_verified boolean) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF p_verified IS NULL THEN RAISE EXCEPTION 'policy observation required'; END IF;
 UPDATE dvnt_settlement.controls SET platform_payout_policy_verified=p_verified,platform_payout_policy_checked_at=now() WHERE singleton;
 RETURN jsonb_build_object('ok',true);
END $$;
REVOKE ALL ON FUNCTION public.settlement_platform_policy_observation(boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_platform_policy_observation(boolean) TO service_role;
CREATE FUNCTION public.settlement_health() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('checkout_enabled',c.checkout_enabled,'transfers_enabled',c.transfers_enabled,
 'recovery_enabled',c.recovery_enabled,'release_policy_configured',EXISTS(SELECT 1 FROM dvnt_settlement.release_policies),
 'platform_payout_policy_verified',c.platform_payout_policy_verified,'platform_payout_policy_checked_at',c.platform_payout_policy_checked_at,
 'schedule_verified',false,'last_started_at',c.last_worker_started_at,'last_completed_at',c.last_worker_completed_at,
 'last_error_at',c.last_worker_error_at,'last_summary',c.last_worker_summary,
 'worker_never_completed',c.last_worker_completed_at IS NULL,
 'oldest_due_at',(SELECT min(due_at) FROM (
  SELECT greatest(s.release_at,coalesce(dvnt_settlement.event_release_at(o.event_id),s.release_at)) AS due_at
  FROM dvnt_settlement.orders s JOIN public.orders o ON o.id=s.order_id
  JOIN dvnt_settlement.allocations a ON a.order_id=s.order_id JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
  WHERE d.state IN ('held','reserved','uncertain') AND a.amount_cents>0
   AND NOT (a.role='promoter' AND dvnt_settlement.promoter_obligation_satisfied(a.id))
  UNION ALL
  SELECT greatest(c.release_not_before,coalesce(dvnt_settlement.event_release_at(o.event_id),c.release_not_before))
  FROM dvnt_settlement.checkouts c JOIN public.orders o ON o.id=c.order_id
  WHERE o.status IN ('paid','partially_refunded','refunded','disputed')
   AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders s WHERE s.order_id=c.order_id)
 ) obligations WHERE due_at<=now()),
 -- Separate operational observation: a provider outcome is unknown, not a
 -- declaration that payment or a debt exists. Future events remain quiet.
 'oldest_checkout_outcome_unknown_at',(SELECT min(greatest(c.outcome_unknown_since,c.release_not_before,dvnt_settlement.event_release_at(o.event_id)))
  FROM dvnt_settlement.checkouts c JOIN public.orders o ON o.id=c.order_id
  WHERE c.outcome_unknown_since IS NOT NULL AND c.retired_at IS NULL
   AND greatest(c.release_not_before,dvnt_settlement.event_release_at(o.event_id))<=now()
   AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.orders s WHERE s.order_id=c.order_id)),
 'blocked_order_count',(SELECT count(*) FROM dvnt_settlement.checkouts WHERE last_error IS NOT NULL),
 'onboarding_or_account_blocked',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE last_error IN ('onboarding_required','recipient_restricted')),
 'organizer_waiting_on_promoter',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE last_error='promoter_pending'),
 'held_promoter_liabilities',(SELECT coalesce(jsonb_object_agg(currency,cents),'{}'::jsonb) FROM (
  SELECT s.currency,sum(a.amount_cents) AS cents FROM dvnt_settlement.allocations a
  JOIN dvnt_settlement.orders s ON s.order_id=a.order_id JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
  WHERE a.role='promoter' AND d.state IN ('held','reserved','uncertain')
   AND NOT dvnt_settlement.promoter_obligation_satisfied(a.id) GROUP BY s.currency) p),
 'funding_blocked',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE last_error='funding_required'),
 'source_audit_blocked',(SELECT count(*) FROM dvnt_settlement.checkouts WHERE last_error IN ('source_audit_limit','source_verification_stale'))+
  (SELECT count(*) FROM dvnt_settlement.deliveries WHERE last_error IN ('source_audit_limit','source_verification_stale')),
 'uncertain_transfers',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE state IN ('reserved','uncertain')),
 'recovery_due',(SELECT count(*) FROM dvnt_settlement.recoveries WHERE state<>'recovered'),
 'quarantined_refunds',(SELECT count(*) FROM dvnt_settlement.refunds WHERE state='quarantined'),
 'unverified_bank_deliveries',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE state='transferred' AND bank_payout_state='unverified'),
 'failed_bank_deliveries',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE bank_payout_state='failed'))
 FROM dvnt_settlement.controls c WHERE singleton;
$$;
REVOKE ALL ON FUNCTION public.settlement_worker_observation(text,jsonb),public.settlement_health() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_worker_observation(text,jsonb),public.settlement_health() TO service_role;
CREATE OR REPLACE FUNCTION public.settlement_actor_summary(p_actor text,p_event_id int) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('verified',true,'rows',coalesce(jsonb_agg(to_jsonb(summary)),'[]'::jsonb)) FROM (
 SELECT s.currency,a.role AS recipient_role,
 CASE WHEN d.state IN ('uncertain','recovery_required') OR d.last_error IS NOT NULL THEN 'needs_review'
 WHEN d.state='held' THEN 'awaiting_settlement'
 WHEN d.state='reserved' THEN 'transfer_submitted'
 WHEN d.bank_payout_state='failed' THEN 'bank_failed'
 WHEN d.bank_payout_state='paid' THEN 'bank_paid'
 WHEN d.bank_payout_state='pending' THEN 'bank_pending'
 ELSE 'in_connected_balance' END AS stage,
 sum(a.amount_cents)::bigint AS amount_cents,count(*)::int AS allocation_count,
 CASE WHEN count(bp.allocation_id)=count(*) THEN sum((bp.proof->>'netContributionCents')::bigint) END AS bank_net_contribution_cents
 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.orders s ON s.order_id=a.order_id
 JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id LEFT JOIN dvnt_settlement.bank_proofs bp ON bp.allocation_id=a.id JOIN public.orders o ON o.id=a.order_id
 WHERE o.event_id=p_event_id AND p_actor IS NOT NULL AND a.recipient_user_id=p_actor
 GROUP BY s.currency,a.role,stage
 ) summary;
$$;




-- SOURCE: docs/payments/drafts/settlement-watchdog.sql

-- Observation only. Inventory is not scheduler activation or proof of alert delivery.
CREATE FUNCTION dvnt_settlement.schedule_inventory() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE n int; visible boolean:=to_regclass('cron.job') IS NOT NULL;
BEGIN
 IF visible THEN
  EXECUTE $q$ SELECT count(*)::int FROM cron.job WHERE active AND
   (command LIKE '%/functions/v1/settlements-process%' OR command ~ '\mcron_settlements_process\M') $q$ INTO n;
 END IF;
 RETURN jsonb_build_object('scheduler_visible',visible,'active_schedules',n);
END $$;
REVOKE ALL ON FUNCTION dvnt_settlement.schedule_inventory() FROM PUBLIC,anon,authenticated,service_role;

-- A typed queue, not a fictitious Refund or provider reversal. Lost/won dispute
-- resolution needs verified dispute evidence and an operator decision. No hold
-- is cleared by observation, and original allocations remain immutable.
CREATE VIEW dvnt_settlement.manual_review_queue AS
 SELECT DISTINCT s.order_id,
 CASE WHEN o.status='refunded' THEN 'dispute_refund_state_review'
 ELSE 'dispute_resolution_review' END::text AS reason
 FROM dvnt_settlement.orders s JOIN public.orders o ON o.id=s.order_id
 WHERE EXISTS(SELECT 1 FROM dvnt_settlement.holds h WHERE h.order_id=s.order_id AND h.reason='dispute')
 UNION
 SELECT a.order_id,'missing_recovery_evidence'::text
 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
 WHERE d.state='recovery_required' AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.recoveries r WHERE r.allocation_id=a.id)
 UNION SELECT order_id,'dispute_currency_outflow_review'::text FROM dvnt_settlement.dispute_outflows
 UNION SELECT order_id,'refund_outcome_review'::text FROM dvnt_settlement.refund_outflows
 WHERE state='uncertain' OR (state IN('attempted','submitted') AND created_at<now()-interval '90 minutes');
REVOKE ALL ON dvnt_settlement.manual_review_queue FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.settlement_manual_review_queue() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM dvnt_settlement.manual_review_queue q;
$$;
REVOKE ALL ON FUNCTION public.settlement_manual_review_queue() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_manual_review_queue() TO service_role;

ALTER FUNCTION public.settlement_health() RENAME TO settlement_health_base;
REVOKE ALL ON FUNCTION public.settlement_health_base() FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.settlement_health() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb; external_health jsonb;
BEGIN
 SELECT public.settlement_health_base() || dvnt_settlement.schedule_inventory() || jsonb_build_object(
  'observed_at',now(),'worker_expected',c.checkout_enabled OR c.transfers_enabled OR c.recovery_enabled,
  'schedule_verified',coalesce((dvnt_settlement.schedule_inventory()->>'active_schedules')::int=1
   AND c.last_worker_completed_at>now()-interval '90 minutes',false),
  'platform_payout_policy_blocked',(SELECT count(*) FROM dvnt_settlement.deliveries WHERE last_error='platform_payout_policy_unverified'),
  'manual_review_count',(SELECT count(*) FROM dvnt_settlement.manual_review_queue)) INTO result
 FROM dvnt_settlement.controls c WHERE singleton;
 -- External draft is assembled last. Late-bound so the override definitions
 -- keep their ordering, but missing external observation never returns green.
 SELECT public.settlement_external_recovery_health() INTO external_health;
 RETURN result || external_health || jsonb_build_object('manual_review_count',
  (result->>'manual_review_count')::bigint+(external_health->>'external_recovery_review_required')::bigint);
END $$;
REVOKE ALL ON FUNCTION public.settlement_health() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_health() TO service_role;

CREATE TABLE dvnt_settlement.readiness_alert_state (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),issue_codes text[] NOT NULL DEFAULT '{}',last_alerted_at timestamptz
);
ALTER TABLE dvnt_settlement.readiness_alert_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.readiness_alert_state FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.claim_settlement_readiness_alert(p_issue_codes text[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE codes text[]; claimed boolean;
BEGIN
 IF p_issue_codes IS NULL OR cardinality(p_issue_codes)>12 OR EXISTS(SELECT 1 FROM unnest(p_issue_codes) code WHERE code IS NULL OR code NOT IN
 ('snapshot_unavailable','checkout_outcome_unknown','due_settlement_attention','bank_delivery_failed','platform_payout_policy_unverified','manual_recovery_review','scheduler_unverified','scheduler_missing','scheduler_duplicate','worker_never_completed','worker_stale','worker_failed'))
 THEN RAISE EXCEPTION 'invalid settlement readiness codes'; END IF;
 SELECT coalesce(array_agg(DISTINCT code ORDER BY code),'{}'::text[]) INTO codes FROM unnest(p_issue_codes) code;
 INSERT INTO dvnt_settlement.readiness_alert_state(singleton) VALUES(true) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM dvnt_settlement.readiness_alert_state WHERE singleton FOR UPDATE;
 IF cardinality(codes)=0 THEN
  UPDATE dvnt_settlement.readiness_alert_state SET issue_codes=codes,last_alerted_at=NULL WHERE singleton; RETURN false;
 END IF;
 UPDATE dvnt_settlement.readiness_alert_state SET issue_codes=codes,last_alerted_at=now()
 WHERE singleton AND (last_alerted_at IS NULL OR last_alerted_at<=now()-interval '1 hour' OR issue_codes IS DISTINCT FROM codes);
 claimed:=FOUND; RETURN claimed;
END $$;
REVOKE ALL ON FUNCTION public.claim_settlement_readiness_alert(text[]) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_settlement_readiness_alert(text[]) TO service_role;


-- SOURCE: docs/payments/drafts/settlement-external.sql
-- DRAFT ONLY. Apply AFTER ledger, runtime, recovery and observability in an isolated
-- test database. Not a production migration; no payment is initiated by this SQL.

-- Empty by default. Only a separately reviewed database administrator can
-- provision operators and already-verified recipient bindings. Event ownership,
-- co-organizer roles, and possession of a promoter link confer no permission.
CREATE TABLE dvnt_settlement.external_operators (
 actor_id text PRIMARY KEY CHECK(length(actor_id) BETWEEN 1 AND 128),
 enabled boolean NOT NULL DEFAULT false
);
CREATE TABLE dvnt_settlement.external_recipients (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 promoter_id uuid NOT NULL REFERENCES public.event_promoters(id),
 provider text NOT NULL CHECK(provider ~ '^[a-z][a-z0-9_-]{1,31}$' AND provider <> 'stripe'),
 beneficiary_reference text NOT NULL CHECK(length(beneficiary_reference) BETWEEN 1 AND 128),
 recipient_user_id text,
 verified_by text NOT NULL REFERENCES dvnt_settlement.external_operators(actor_id),
 verified_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(promoter_id,provider,beneficiary_reference)
);
CREATE TABLE dvnt_settlement.external_promoter_payments (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 request_key uuid NOT NULL UNIQUE,
 event_id int NOT NULL REFERENCES public.events(id),
 promoter_id uuid NOT NULL REFERENCES public.event_promoters(id),
 recipient_binding_id uuid NOT NULL REFERENCES dvnt_settlement.external_recipients(id),
 recipient_user_id text,
 actor_id text NOT NULL REFERENCES dvnt_settlement.external_operators(actor_id),
 provider text NOT NULL,
 transaction_reference text NOT NULL CHECK(length(transaction_reference) BETWEEN 1 AND 160),
 receipt_sha256 text NOT NULL UNIQUE CHECK(receipt_sha256 ~ '^[a-f0-9]{64}$'),
 -- Opaque reference to an access-controlled, immutable receipt object/version,
 -- never a public URL, account number, raw receipt body, or fabricated Stripe ID.
 receipt_reference text NOT NULL CHECK(receipt_reference ~ '^[a-z][a-z0-9_-]{0,31}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,63}$'),
 evidence_status text NOT NULL CHECK(evidence_status='completed'),
 attestation jsonb NOT NULL,
 paid_at timestamptz NOT NULL CHECK(isfinite(paid_at)),
 amount_cents bigint NOT NULL CHECK(amount_cents>0),
 currency text NOT NULL CHECK(currency ~ '^[a-z]{3}$'),
 ledger_entry_ids uuid[] NOT NULL,
 recorded_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(provider,transaction_reference)
);
ALTER TABLE public.promoter_ledger_entries ADD COLUMN external_settlement_id uuid
 REFERENCES dvnt_settlement.external_promoter_payments(id);
CREATE TABLE dvnt_settlement.external_promoter_rows (
 ledger_entry_id uuid PRIMARY KEY REFERENCES public.promoter_ledger_entries(id),
 settlement_id uuid NOT NULL REFERENCES dvnt_settlement.external_promoter_payments(id),
 order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id),
 promoter_id uuid NOT NULL REFERENCES public.event_promoters(id),
 amount_cents bigint NOT NULL CHECK(amount_cents>0),
 currency text NOT NULL,
 recipient_user_id text
);
-- This barrier survives event hold clearing, release-date changes and all
-- promoter bookkeeping. Never calculate another aggregate organizer payout.
CREATE TABLE dvnt_settlement.external_event_exclusions (
 event_id int PRIMARY KEY REFERENCES public.events(id),
 first_settlement_id uuid NOT NULL REFERENCES dvnt_settlement.external_promoter_payments(id),
 created_at timestamptz NOT NULL DEFAULT now()
);
-- Permanent tombstone: a legacy runner might have crossed its DB claim and be
-- executing against Stripe. No timeout or reset can prove that it did not pay.
CREATE TABLE dvnt_settlement.legacy_execution_claims (
 event_id int PRIMARY KEY REFERENCES public.events(id),
 created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE dvnt_settlement.external_recovery_reviews (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 settlement_id uuid NOT NULL REFERENCES dvnt_settlement.external_promoter_payments(id),
 order_id uuid NOT NULL REFERENCES public.orders(id),
 reason text NOT NULL CHECK(reason IN ('refund','dispute','manual','cancellation','ledger_reversal')),
 source_reference text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(order_id,reason,source_reference)
);

CREATE FUNCTION dvnt_settlement.reject_external_change() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION 'external settlement evidence is immutable'; END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['external_recipients','external_promoter_payments','external_promoter_rows','external_event_exclusions','legacy_execution_claims','external_recovery_reviews'] LOOP
  EXECUTE format('CREATE TRIGGER immutable_external BEFORE UPDATE OR DELETE ON dvnt_settlement.%I FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.reject_external_change()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['external_operators','external_recipients','external_promoter_payments','external_promoter_rows','external_event_exclusions','legacy_execution_claims','external_recovery_reviews'] LOOP
  EXECUTE format('ALTER TABLE dvnt_settlement.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON dvnt_settlement.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;

-- Old ('processing') event claims serialize on the event row with recording.
-- The conservative runner MUST use settlement_claim_legacy_event below; an
-- ordinary dispute/manual on_hold update is not proof of financial execution.
-- Existing claims before installation cannot be inferred: drain all old workers
-- and audit in-flight/uncertain outcomes before enabling this recording RPC.
CREATE FUNCTION dvnt_settlement.guard_legacy_event_claim() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NEW.payout_status='processing' AND NEW.payout_status IS DISTINCT FROM OLD.payout_status THEN
  IF EXISTS(SELECT 1 FROM dvnt_settlement.external_event_exclusions WHERE event_id=NEW.id) THEN
   RAISE EXCEPTION 'external settlement excludes legacy event execution';
  END IF;
  INSERT INTO dvnt_settlement.legacy_execution_claims(event_id) VALUES(NEW.id) ON CONFLICT DO NOTHING;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER external_legacy_event_claim BEFORE UPDATE ON public.events
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.guard_legacy_event_claim();

-- Atomic financial claim replaces the conservative worker's naked on_hold CAS.
CREATE FUNCTION public.settlement_claim_legacy_event(p_event_id int) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE e public.events%ROWTYPE;
BEGIN
 SELECT * INTO STRICT e FROM public.events WHERE id=p_event_id FOR UPDATE;
 IF e.payout_status IS DISTINCT FROM 'pending' THEN RETURN jsonb_build_object('claimed',false); END IF;
 IF EXISTS(SELECT 1 FROM dvnt_settlement.external_event_exclusions WHERE event_id=e.id)
 OR EXISTS(SELECT 1 FROM dvnt_settlement.legacy_execution_claims WHERE event_id=e.id)
 OR EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c JOIN public.orders o ON o.id=c.order_id WHERE o.event_id=e.id)
 THEN RAISE EXCEPTION 'legacy event execution excluded or previously claimed'; END IF;
 INSERT INTO dvnt_settlement.legacy_execution_claims(event_id) VALUES(e.id);
 UPDATE public.events SET payout_status='on_hold' WHERE id=e.id;
 RETURN jsonb_build_object('claimed',true);
END $$;
REVOKE ALL ON FUNCTION public.settlement_claim_legacy_event(int) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_claim_legacy_event(int) TO service_role;

CREATE FUNCTION dvnt_settlement.guard_legacy_payout() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 PERFORM 1 FROM public.events WHERE id=NEW.event_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM dvnt_settlement.external_event_exclusions WHERE event_id=NEW.event_id) THEN
  RAISE EXCEPTION 'external settlement excludes legacy payout';
 END IF;
 INSERT INTO dvnt_settlement.legacy_execution_claims(event_id) VALUES(NEW.event_id) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
CREATE TRIGGER external_legacy_payout BEFORE INSERT OR UPDATE ON public.payouts
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.guard_legacy_payout();

-- Exact source lock is shared by external recording and the Stripe reserver.
-- Also protects low-level/private calls, not just the public worker RPC.
CREATE FUNCTION dvnt_settlement.guard_external_delivery() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a dvnt_settlement.allocations%ROWTYPE;
BEGIN
 -- Bank proof/failure bookkeeping already locks delivery first. It cannot
 -- initiate another transfer, so do not invert the source→delivery lock order.
 IF TG_OP='UPDATE' AND ROW(NEW.state,NEW.stripe_transfer_id)
 IS NOT DISTINCT FROM ROW(OLD.state,OLD.stripe_transfer_id) THEN RETURN NEW; END IF;
 IF NEW.state='held' AND NEW.stripe_transfer_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT a FROM dvnt_settlement.allocations WHERE id=NEW.allocation_id;
 PERFORM 1 FROM public.orders WHERE id=a.order_id FOR UPDATE;
 IF a.role='promoter' AND (NEW.state<>'held' OR NEW.stripe_transfer_id IS NOT NULL)
 AND EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=a.order_id) THEN
  RAISE EXCEPTION 'promoter obligation already settled externally';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER external_delivery_interlock BEFORE INSERT OR UPDATE ON dvnt_settlement.deliveries
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.guard_external_delivery();

-- The settlement stamp can never be erased or converted into a Stripe transfer.
-- Later refund reversal entries remain possible and are separate obligations.
CREATE FUNCTION dvnt_settlement.guard_external_ledger() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE x dvnt_settlement.external_promoter_rows%ROWTYPE; paid timestamptz;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.external_settlement_id IS NOT NULL THEN RAISE EXCEPTION 'external settlement linkage requires protected recording'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO x FROM dvnt_settlement.external_promoter_rows WHERE ledger_entry_id=OLD.id;
 IF NOT FOUND THEN
  IF TG_OP='UPDATE' AND NEW.external_settlement_id IS NOT NULL THEN RAISE EXCEPTION 'external settlement linkage requires protected recording'; END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'externally settled ledger is immutable'; END IF;
 SELECT paid_at INTO STRICT paid FROM dvnt_settlement.external_promoter_payments WHERE id=x.settlement_id;
 IF ROW(NEW.id,NEW.order_id,NEW.event_id,NEW.promoter_id,NEW.entry_type,NEW.amount_cents,NEW.currency)
 IS DISTINCT FROM ROW(OLD.id,OLD.order_id,OLD.event_id,OLD.promoter_id,OLD.entry_type,OLD.amount_cents,OLD.currency)
 OR NEW.paid_out_at IS DISTINCT FROM paid OR NEW.payout_status IS DISTINCT FROM 'paid'
 OR NEW.external_settlement_id IS DISTINCT FROM x.settlement_id
 OR NEW.stripe_transfer_id IS NOT NULL THEN RAISE EXCEPTION 'externally settled ledger is immutable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER external_ledger_interlock BEFORE INSERT OR UPDATE OR DELETE ON public.promoter_ledger_entries
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.guard_external_ledger();

-- Legacy source identity/economics also remain frozen; moving a paid order to
-- another event must never escape that event's permanent aggregate exclusion.
CREATE FUNCTION dvnt_settlement.freeze_external_source() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows WHERE order_id=OLD.id)
 AND ROW(NEW.id,NEW.event_id,NEW.charge_model,NEW.stripe_payment_intent_id,NEW.currency,NEW.total_cents,
 NEW.subtotal_cents,NEW.organizer_fee_cents,NEW.promoter_id,NEW.promoter_code,NEW.promoter_commission_amount_cents,NEW.type)
 IS DISTINCT FROM ROW(OLD.id,OLD.event_id,OLD.charge_model,OLD.stripe_payment_intent_id,OLD.currency,OLD.total_cents,
 OLD.subtotal_cents,OLD.organizer_fee_cents,OLD.promoter_id,OLD.promoter_code,OLD.promoter_commission_amount_cents,OLD.type)
 THEN RAISE EXCEPTION 'externally settled source economics are immutable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER external_source_freeze BEFORE UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.freeze_external_source();

-- Service-only attestation API, not an end-user endpoint. p_actor MUST come from
-- the trusted operator's verified session, never an arbitrary request body.
-- Receipt bytes, provider completion and beneficiary must be independently
-- reviewed BEFORE this call. The DB verifies exact scope, not receipt authenticity.
CREATE FUNCTION public.settlement_record_external_promoter_payment(
 p_actor text, p_request_key uuid, p_event_id int, p_promoter_id uuid,
 p_recipient_binding_id uuid, p_ledger_entry_ids uuid[], p_amount_cents bigint,
 p_currency text, p_provider text, p_transaction_reference text,
 p_receipt_sha256 text, p_receipt_reference text, p_evidence_status text,
 p_paid_at timestamptz, p_receipt_beneficiary_reference text, p_attestation jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE existing dvnt_settlement.external_promoter_payments%ROWTYPE;
 recipient dvnt_settlement.external_recipients%ROWTYPE; promoter public.event_promoters%ROWTYPE;
 e public.events%ROWTYPE; ids uuid[]; row_count int; total bigint; sid uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_operators WHERE actor_id=p_actor AND enabled) THEN
  RAISE EXCEPTION 'external settlement operator not authorized'; END IF;
 IF p_attestation IS DISTINCT FROM '{"independently_checked_completed_final":true,"receipt_retained":true,"recipient_and_details_match":true}'::jsonb
 OR p_receipt_beneficiary_reference IS NULL
 OR p_request_key IS NULL OR p_evidence_status IS DISTINCT FROM 'completed'
 OR p_paid_at IS NULL OR NOT isfinite(p_paid_at) OR p_paid_at>clock_timestamp()
 OR p_amount_cents IS NULL OR p_amount_cents<=0 OR p_currency IS NULL OR p_currency !~ '^[a-z]{3}$'
 OR p_provider IS NULL OR p_provider !~ '^[a-z][a-z0-9_-]{1,31}$' OR p_provider='stripe'
 OR p_transaction_reference IS NULL OR p_transaction_reference<>btrim(p_transaction_reference)
 OR length(p_transaction_reference) NOT BETWEEN 1 AND 160
 OR p_receipt_sha256 IS NULL OR p_receipt_sha256 !~ '^[a-f0-9]{64}$'
 OR p_receipt_reference IS NULL OR p_receipt_reference<>btrim(p_receipt_reference)
 OR p_receipt_reference !~ '^[a-z][a-z0-9_-]{0,31}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,63}$'
 OR p_ledger_entry_ids IS NULL OR cardinality(p_ledger_entry_ids) NOT BETWEEN 1 AND 1000
 OR array_position(p_ledger_entry_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'completed payment evidence and exact scope required'; END IF;
 SELECT array_agg(id ORDER BY id) INTO ids FROM (SELECT DISTINCT unnest(p_ledger_entry_ids) id) q;
 IF cardinality(ids)<>cardinality(p_ledger_entry_ids) THEN RAISE EXCEPTION 'duplicate ledger scope'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('external:'||p_request_key::text,0));
 SELECT * INTO existing FROM dvnt_settlement.external_promoter_payments WHERE request_key=p_request_key;
 IF FOUND THEN
  IF ROW(existing.actor_id,existing.event_id,existing.promoter_id,existing.recipient_binding_id,existing.ledger_entry_ids,
    existing.amount_cents,existing.currency,existing.provider,existing.transaction_reference,existing.receipt_sha256,
    existing.receipt_reference,existing.evidence_status,existing.paid_at,existing.attestation)
  IS DISTINCT FROM ROW(p_actor,p_event_id,p_promoter_id,p_recipient_binding_id,ids,p_amount_cents,p_currency,p_provider,
    p_transaction_reference,p_receipt_sha256,p_receipt_reference,p_evidence_status,p_paid_at,p_attestation)
  THEN RAISE EXCEPTION 'external payment replay mismatch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_recipients WHERE id=existing.recipient_binding_id AND beneficiary_reference=p_receipt_beneficiary_reference) THEN RAISE EXCEPTION 'recipient binding mismatch'; END IF;
  RETURN jsonb_build_object('id',existing.id,'recorded',true,'status','paid_externally','replayed',true);
 END IF;
 SELECT * INTO STRICT e FROM public.events WHERE id=p_event_id FOR UPDATE;
 -- Require a deliberate quarantine. This does not bypass event/order holds.
 IF e.payout_status IS DISTINCT FROM 'on_hold' OR e.payout_release_at IS NOT NULL
 OR e.status IN ('cancelled','canceled')
 OR EXISTS(SELECT 1 FROM dvnt_settlement.legacy_execution_claims WHERE event_id=e.id)
 OR EXISTS(SELECT 1 FROM public.payouts WHERE event_id=e.id) THEN RAISE EXCEPTION 'event execution requires reconciliation'; END IF;
 SELECT * INTO STRICT promoter FROM public.event_promoters WHERE id=p_promoter_id FOR SHARE;
 SELECT * INTO STRICT recipient FROM dvnt_settlement.external_recipients WHERE id=p_recipient_binding_id;
 IF promoter.event_id IS DISTINCT FROM p_event_id OR recipient.promoter_id IS DISTINCT FROM p_promoter_id
 OR recipient.recipient_user_id IS DISTINCT FROM promoter.user_id
 OR recipient.provider IS DISTINCT FROM p_provider OR recipient.beneficiary_reference IS DISTINCT FROM p_receipt_beneficiary_reference THEN RAISE EXCEPTION 'recipient binding mismatch'; END IF;
 -- Lock source orders in deterministic order, exactly as the transfer reserver
 -- does; a prior reserved/uncertain/transferred intent wins and requires review.
 PERFORM 1 FROM public.orders WHERE id IN(SELECT order_id FROM public.promoter_ledger_entries WHERE id=ANY(ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 PERFORM 1 FROM public.promoter_ledger_entries WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 SELECT count(*),coalesce(sum(l.amount_cents),0) INTO row_count,total
 FROM public.promoter_ledger_entries l JOIN public.orders o ON o.id=l.order_id
 JOIN public.promoter_attributions pa ON pa.order_id=o.id AND pa.promoter_id=l.promoter_id
 WHERE l.id=ANY(ids) AND l.event_id=p_event_id AND o.event_id=p_event_id AND l.promoter_id=p_promoter_id
 AND l.entry_type='earning' AND l.amount_cents>0 AND l.currency=p_currency AND o.currency=p_currency
 AND o.status='paid' AND o.type='event_ticket' AND l.paid_out_at IS NULL AND l.stripe_transfer_id IS NULL AND l.payout_status IN ('pending','held')
 AND NOT EXISTS(SELECT 1 FROM public.promoter_ledger_entries reversal WHERE reversal.order_id=o.id AND reversal.entry_type='reversal')
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.holds h WHERE h.order_id=o.id)
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c WHERE c.order_id=o.id AND
  (coalesce(c.last_error,'') LIKE 'hold:%' OR c.promoter_id IS DISTINCT FROM p_promoter_id
   OR c.promoter_user_id IS DISTINCT FROM recipient.recipient_user_id
   OR (c.snapshot->'order'->>'promoter_commission_amount_cents')::bigint IS DISTINCT FROM l.amount_cents::bigint
   OR c.snapshot->'order'->>'currency' IS DISTINCT FROM p_currency))
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
  WHERE a.order_id=o.id AND a.role='promoter' AND (d.state<>'held' OR d.stripe_transfer_id IS NOT NULL))
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.orders s ON s.order_id=a.order_id
  WHERE a.order_id=o.id AND a.role='promoter' AND (a.recipient_id<>p_promoter_id::text OR a.recipient_user_id IS DISTINCT FROM recipient.recipient_user_id OR a.amount_cents<>l.amount_cents OR s.currency<>p_currency))
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=o.id);
 IF row_count<>cardinality(ids) OR total<>p_amount_cents THEN RAISE EXCEPTION 'ledger scope count, amount, recipient, currency or eligibility mismatch'; END IF;
 INSERT INTO dvnt_settlement.external_promoter_payments(request_key,event_id,promoter_id,recipient_binding_id,recipient_user_id,
 actor_id,provider,transaction_reference,receipt_sha256,receipt_reference,evidence_status,paid_at,amount_cents,currency,ledger_entry_ids,attestation)
 VALUES(p_request_key,p_event_id,p_promoter_id,p_recipient_binding_id,recipient.recipient_user_id,p_actor,p_provider,p_transaction_reference,
 p_receipt_sha256,p_receipt_reference,p_evidence_status,p_paid_at,p_amount_cents,p_currency,ids,p_attestation) RETURNING id INTO sid;
 INSERT INTO dvnt_settlement.external_promoter_rows(ledger_entry_id,settlement_id,order_id,promoter_id,amount_cents,currency,recipient_user_id)
 SELECT l.id,sid,l.order_id,l.promoter_id,l.amount_cents,l.currency,recipient.recipient_user_id FROM public.promoter_ledger_entries l WHERE l.id=ANY(ids);
 INSERT INTO dvnt_settlement.external_event_exclusions(event_id,first_settlement_id) VALUES(p_event_id,sid) ON CONFLICT DO NOTHING;
 UPDATE public.promoter_ledger_entries SET paid_out_at=p_paid_at,payout_status='paid',external_settlement_id=sid,
 payout_note='Paid externally; protected receipt-backed settlement' WHERE id=ANY(ids) AND paid_out_at IS NULL;
 GET DIAGNOSTICS row_count=ROW_COUNT;
 IF row_count<>cardinality(ids) THEN RAISE EXCEPTION 'external settlement stamp count mismatch'; END IF;
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN jsonb_build_object('id',sid,'recorded',true,'status','paid_externally','replayed',false);
END $$;

-- Contract shared with promoter-first host reservation. External evidence never
-- masquerades as Stripe transfer or bank-payout membership. Recovery holds win.
CREATE OR REPLACE FUNCTION dvnt_settlement.promoter_obligation_satisfied(p_allocation uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM dvnt_settlement.allocations a
 JOIN dvnt_settlement.orders s ON s.order_id=a.order_id JOIN public.orders o ON o.id=a.order_id
 JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id
 WHERE a.id=p_allocation AND a.role='promoter' AND o.status='paid'
 AND NOT s.blocked AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_recovery_reviews r WHERE r.order_id=a.order_id)
 AND NOT EXISTS(SELECT 1 FROM public.promoter_ledger_entries r WHERE r.order_id=a.order_id AND r.entry_type='reversal')
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.holds h WHERE h.order_id=a.order_id)
 AND ((d.state='transferred' AND d.stripe_transfer_id IS NOT NULL)
 OR (d.state='held' AND d.stripe_transfer_id IS NULL AND EXISTS(
  SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=a.order_id
  AND x.promoter_id::text=a.recipient_id AND x.recipient_user_id IS NOT DISTINCT FROM a.recipient_user_id
  AND x.amount_cents=a.amount_cents AND x.currency=s.currency))));
$$;

CREATE OR REPLACE FUNCTION public.settlement_legacy_event_eligible(p_event_id int) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('eligible',NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c
 JOIN public.orders o ON o.id=c.order_id WHERE o.event_id=p_event_id)
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_event_exclusions WHERE event_id=p_event_id));
$$;
CREATE OR REPLACE FUNCTION public.settlement_actor_summary(p_actor text,p_event_id int) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('verified',true,'rows',coalesce(jsonb_agg(to_jsonb(summary)),'[]'::jsonb)) FROM (
 SELECT s.currency,a.role AS recipient_role,
 CASE WHEN d.state IN ('uncertain','recovery_required') OR d.last_error IS NOT NULL THEN 'needs_review'
 WHEN d.state='held' THEN 'awaiting_settlement' WHEN d.state='reserved' THEN 'transfer_submitted'
 WHEN d.bank_payout_state='failed' THEN 'bank_failed' WHEN d.bank_payout_state='paid' THEN 'bank_paid'
 WHEN d.bank_payout_state='pending' THEN 'bank_pending' ELSE 'in_connected_balance' END AS stage,
 sum(a.amount_cents)::bigint AS amount_cents,count(*)::int AS allocation_count,
 CASE WHEN count(bp.allocation_id)=count(*) THEN sum((bp.proof->>'netContributionCents')::bigint) END AS bank_net_contribution_cents
 FROM dvnt_settlement.allocations a JOIN dvnt_settlement.orders s ON s.order_id=a.order_id
 JOIN dvnt_settlement.deliveries d ON d.allocation_id=a.id LEFT JOIN dvnt_settlement.bank_proofs bp ON bp.allocation_id=a.id
 JOIN public.orders o ON o.id=a.order_id
 WHERE o.event_id=p_event_id AND p_actor IS NOT NULL AND a.recipient_user_id=p_actor
 AND NOT(a.role='promoter' AND EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=a.order_id))
 GROUP BY s.currency,a.role,stage
 UNION ALL
 SELECT x.currency,'promoter',CASE WHEN o.status<>'paid' OR EXISTS(SELECT 1 FROM dvnt_settlement.external_recovery_reviews r WHERE r.order_id=o.id)
 OR EXISTS(SELECT 1 FROM public.promoter_ledger_entries r WHERE r.order_id=o.id AND r.entry_type='reversal')
 OR EXISTS(SELECT 1 FROM dvnt_settlement.holds h WHERE h.order_id=o.id)
 THEN 'external_needs_review' ELSE 'paid_externally' END,
 sum(x.amount_cents)::bigint,count(*)::int,NULL::bigint
 FROM dvnt_settlement.external_promoter_rows x JOIN dvnt_settlement.external_promoter_payments p ON p.id=x.settlement_id
 JOIN public.orders o ON o.id=x.order_id
 WHERE p.event_id=p_event_id AND p_actor IS NOT NULL AND x.recipient_user_id=p_actor
 GROUP BY x.currency,3
 ) summary;
$$;

-- Append-only recovery provenance. External money cannot be reversed through
-- Stripe; a later refund/dispute/reversal requires an explicit manual workflow.
CREATE FUNCTION dvnt_settlement.flag_external_recovery() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oid uuid; why text; ref text;
BEGIN
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='orders' THEN
  IF NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.status NOT IN ('refunded','partially_refunded','disputed','cancelled','canceled') THEN RETURN NEW; END IF;
  oid:=NEW.id; why:=CASE WHEN NEW.status='disputed' THEN 'dispute' WHEN NEW.status IN ('cancelled','canceled') THEN 'cancellation' ELSE 'refund' END;
  ref:='order-state:'||NEW.status;
 ELSIF TG_TABLE_SCHEMA='dvnt_settlement' AND TG_TABLE_NAME='checkouts' THEN
  IF NEW.last_error IS NOT DISTINCT FROM OLD.last_error OR coalesce(NEW.last_error,'') NOT IN ('hold:refund','hold:dispute','hold:manual') THEN RETURN NEW; END IF;
  oid:=NEW.order_id; why:=substring(NEW.last_error FROM 6); ref:='checkout:'||NEW.last_error;
 ELSIF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='promoter_ledger_entries' THEN
  IF NEW.entry_type<>'reversal' THEN RETURN NEW; END IF;
  oid:=NEW.order_id; why:='ledger_reversal'; ref:='ledger:'||NEW.id::text;
 ELSE
  oid:=NEW.order_id; why:=NEW.reason; ref:='hold:'||NEW.external_event_id;
 END IF;
 INSERT INTO dvnt_settlement.external_recovery_reviews(settlement_id,order_id,reason,source_reference)
 SELECT x.settlement_id,oid,why,ref FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=oid
 ON CONFLICT(order_id,reason,source_reference) DO NOTHING;
 RETURN NEW;
END $$;
CREATE TRIGGER external_order_recovery AFTER UPDATE ON public.orders
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.flag_external_recovery();
CREATE TRIGGER external_reversal_recovery AFTER INSERT ON public.promoter_ledger_entries
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.flag_external_recovery();
CREATE TRIGGER external_checkout_recovery AFTER UPDATE OF last_error ON dvnt_settlement.checkouts
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.flag_external_recovery();
CREATE TRIGGER external_hold_recovery AFTER INSERT ON dvnt_settlement.holds
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.flag_external_recovery();

CREATE FUNCTION public.settlement_external_recovery_candidates(p_limit int DEFAULT 100) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM (
 SELECT r.id,r.settlement_id,r.order_id,r.reason,r.created_at,x.amount_cents,x.currency,
 'manual_external_payment_recovery_review'::text AS action
 FROM dvnt_settlement.external_recovery_reviews r JOIN dvnt_settlement.external_promoter_rows x ON x.order_id=r.order_id
 ORDER BY r.created_at,r.id LIMIT greatest(1,least(p_limit,100))
 ) q;
$$;
CREATE FUNCTION public.settlement_external_recovery_health() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('external_recovery_review_required',count(DISTINCT order_id))
 FROM dvnt_settlement.external_recovery_reviews;
$$;
REVOKE ALL ON FUNCTION public.settlement_external_recovery_candidates(int),public.settlement_external_recovery_health() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_external_recovery_candidates(int),public.settlement_external_recovery_health() TO service_role;

CREATE FUNCTION public.settlement_external_operator_allowed(p_actor text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM dvnt_settlement.external_operators WHERE actor_id=p_actor AND enabled);
$$;
REVOKE ALL ON FUNCTION public.settlement_external_operator_allowed(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_external_operator_allowed(text) TO service_role;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA dvnt_settlement FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.settlement_record_external_promoter_payment(text,uuid,int,uuid,uuid,uuid[],bigint,text,text,text,text,text,text,timestamptz,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_record_external_promoter_payment(text,uuid,int,uuid,uuid,uuid[],bigint,text,text,text,text,text,text,timestamptz,text,jsonb) TO service_role;


-- SOURCE: docs/payments/drafts/settlement-legacy-ownership.sql
-- Reviewed identity/economics bridge ONLY. Default empty. No payment-state writes.
-- Provisioning needs separately authorized human identity review and DBA rollout;
-- current roster ownership is never evidence. Apply after settlement-external.sql.

-- Earlier policies keyed raw financial reads to the mutable promoter roster.
-- No app clients use these raw tables; host/promoter service endpoints retain
-- access. Financial client reads must use authenticated, frozen-actor summaries.
REVOKE SELECT ON public.promoter_ledger_entries, public.promoter_attributions FROM PUBLIC,anon,authenticated;
CREATE TABLE dvnt_settlement.legacy_ownership (
 ledger_entry_id uuid PRIMARY KEY REFERENCES public.promoter_ledger_entries(id),
 order_id uuid NOT NULL REFERENCES public.orders(id),
 promoter_id uuid NOT NULL REFERENCES public.event_promoters(id),
 event_id int NOT NULL REFERENCES public.events(id),
 actor_id text NOT NULL CHECK(length(actor_id) BETWEEN 1 AND 128),
 amount_cents bigint NOT NULL CHECK(amount_cents>0),
 currency text NOT NULL CHECK(currency ~ '^[a-z]{3}$'),
 ledger_created_at timestamptz NOT NULL,
 order_charge_model text CHECK(order_charge_model IS NULL OR order_charge_model='destination_charge'),
 order_total_cents bigint NOT NULL,
 reviewed_by text NOT NULL CHECK(length(reviewed_by) BETWEEN 1 AND 128),
 evidence_reference text NOT NULL CHECK(evidence_reference ~ '^[a-z][a-z0-9_-]{0,31}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,63}$'),
 evidence_sha256 text NOT NULL CHECK(evidence_sha256 ~ '^[a-f0-9]{64}$'),
 reviewed_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE dvnt_settlement.legacy_ownership ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.legacy_ownership FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION dvnt_settlement.check_legacy_ownership() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE l public.promoter_ledger_entries%ROWTYPE; o public.orders%ROWTYPE;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('legacy-ownership:'||NEW.order_id::text,0));
 SELECT * INTO o FROM public.orders WHERE id=NEW.order_id FOR UPDATE;
 SELECT * INTO l FROM public.promoter_ledger_entries WHERE id=NEW.ledger_entry_id FOR UPDATE;
 IF l.id IS NULL OR o.id IS NULL OR l.order_id IS DISTINCT FROM NEW.order_id OR l.promoter_id IS DISTINCT FROM NEW.promoter_id
 OR l.event_id IS DISTINCT FROM NEW.event_id OR o.event_id IS DISTINCT FROM NEW.event_id OR o.promoter_id IS DISTINCT FROM NEW.promoter_id
 OR l.amount_cents IS DISTINCT FROM NEW.amount_cents OR l.currency IS DISTINCT FROM NEW.currency OR o.currency IS DISTINCT FROM NEW.currency
 OR l.created_at IS DISTINCT FROM NEW.ledger_created_at OR l.entry_type IS DISTINCT FROM 'earning'
 OR l.external_settlement_id IS NOT NULL OR o.status IS DISTINCT FROM 'paid'
 OR o.charge_model IS DISTINCT FROM NEW.order_charge_model OR o.charge_model='separate_charges_and_transfers'
 OR o.total_cents IS DISTINCT FROM NEW.order_total_cents
 OR NOT isfinite(NEW.reviewed_at) OR NEW.reviewed_at>clock_timestamp()
 OR EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c WHERE c.order_id=o.id)
 OR EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=o.id)
 OR EXISTS(SELECT 1 FROM public.promoter_ledger_entries r WHERE r.order_id=o.id AND r.entry_type='reversal')
 OR EXISTS(SELECT 1 FROM dvnt_settlement.legacy_ownership b WHERE b.order_id=o.id AND b.actor_id<>NEW.actor_id)
 THEN RAISE EXCEPTION 'reviewed legacy ownership binding mismatch'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER validate_legacy_ownership BEFORE INSERT ON dvnt_settlement.legacy_ownership
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.check_legacy_ownership();
CREATE TRIGGER immutable_legacy_ownership BEFORE UPDATE OR DELETE ON dvnt_settlement.legacy_ownership
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.reject_external_change();
CREATE TRIGGER no_truncate_legacy_ownership BEFORE TRUNCATE ON dvnt_settlement.legacy_ownership
 FOR EACH STATEMENT EXECUTE FUNCTION dvnt_settlement.reject_external_change();

CREATE FUNCTION public.settlement_legacy_actor_summary(p_actor text,p_event_id int) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 WITH reviewed AS (
 SELECT b.order_id,b.currency,sum(b.amount_cents)::bigint AS amount_cents,count(*)::int AS allocation_count,
 bool_and(coalesce(l.id IS NOT NULL AND l.order_id=b.order_id AND l.promoter_id=b.promoter_id AND l.event_id=b.event_id
  AND l.amount_cents=b.amount_cents AND l.currency=b.currency AND l.created_at=b.ledger_created_at
  AND l.external_settlement_id IS NULL AND l.entry_type='earning' AND o.event_id=b.event_id AND o.promoter_id=b.promoter_id
  AND o.currency=b.currency AND o.total_cents=b.order_total_cents AND o.status='paid'
  AND o.charge_model IS NOT DISTINCT FROM b.order_charge_model,false))
 AND (SELECT count(*) FROM public.promoter_ledger_entries r WHERE r.order_id=b.order_id)=count(*) AS intact
 FROM dvnt_settlement.legacy_ownership b LEFT JOIN public.promoter_ledger_entries l ON l.id=b.ledger_entry_id
 LEFT JOIN public.orders o ON o.id=b.order_id
 WHERE b.actor_id=p_actor AND b.event_id=p_event_id
 -- A later external payment owns its entire order's financial presentation,
 -- including subsequent recovery review. Never duplicate it here.
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.external_promoter_rows x WHERE x.order_id=b.order_id)
 AND NOT EXISTS(SELECT 1 FROM dvnt_settlement.checkouts c WHERE c.order_id=b.order_id)
 GROUP BY b.order_id,b.currency
 ), summary AS (
 SELECT currency,'promoter'::text AS recipient_role,
 CASE WHEN intact IS TRUE THEN 'legacy_ownership_verified' ELSE 'legacy_ownership_needs_review' END AS stage,
 CASE WHEN intact IS TRUE THEN sum(amount_cents)::bigint END AS amount_cents,sum(allocation_count)::int AS allocation_count
 FROM reviewed GROUP BY currency,intact
 ) SELECT jsonb_build_object('verified',true,'rows',coalesce(jsonb_agg(to_jsonb(summary)),'[]'::jsonb)) FROM summary;
$$;
REVOKE ALL ON FUNCTION dvnt_settlement.check_legacy_ownership(),public.settlement_legacy_actor_summary(text,int) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_legacy_actor_summary(text,int) TO service_role;
-- Older service-only writer migrations revoked PUBLIC but may have retained
-- explicit client grants from Supabase default privileges. Preserve service
-- access; never let a client manufacture the legacy evidence being reviewed.
DO $body$
DECLARE signature text; target regprocedure;
BEGIN
 FOREACH signature IN ARRAY ARRAY['public.record_promoter_attribution(uuid,text)',
  'public.record_promoter_ledger_entry(uuid,uuid,text,integer,text,text)'] LOOP
  target:=to_regprocedure(signature);
  IF target IS NOT NULL THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',target); END IF;
 END LOOP;
END $body$;



-- SOURCE: docs/payments/drafts/settlement-funding.sql
-- DRAFT: assemble LAST. Empty policy; no opening balance is ever credited.
-- This ledger is not physical provider segregation.

CREATE TABLE dvnt_settlement.funding_policy (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 platform_account text NOT NULL CHECK(platform_account ~ '^acct_[A-Za-z0-9_]+$'),
 livemode boolean NOT NULL, audit_from bigint NOT NULL CHECK(audit_from>=0),
 policy_reference text NOT NULL CHECK(length(btrim(policy_reference))>0)
);
CREATE TABLE dvnt_settlement.funding_sources (
 order_id uuid PRIMARY KEY REFERENCES dvnt_settlement.orders(order_id),
 transaction_id text NOT NULL UNIQUE, proof jsonb NOT NULL,
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE dvnt_settlement.funding_debits (
 transaction_id text PRIMARY KEY, currency text NOT NULL,
 net_cents bigint NOT NULL CHECK(net_cents<0), proof jsonb NOT NULL
);
CREATE TABLE dvnt_settlement.funding_audits (
 currency text PRIMARY KEY, funding_epoch bigint NOT NULL,
 available_cents bigint NOT NULL CHECK(available_cents>=0),
 provider_available_cents bigint NOT NULL CHECK(provider_available_cents>=0),
 credited_cents bigint NOT NULL CHECK(credited_cents>=0),
 debited_cents bigint NOT NULL CHECK(debited_cents>=0),
 observed_at timestamptz NOT NULL, transaction_count integer NOT NULL
);
ALTER TABLE dvnt_settlement.funding_policy ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.funding_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.funding_debits ENABLE ROW LEVEL SECURITY;
ALTER TABLE dvnt_settlement.funding_audits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON dvnt_settlement.funding_policy,dvnt_settlement.funding_sources,
 dvnt_settlement.funding_debits,dvnt_settlement.funding_audits FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable_funding_policy BEFORE UPDATE OR DELETE ON dvnt_settlement.funding_policy
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.reject_allocation_change();
CREATE TRIGGER immutable_funding_source BEFORE UPDATE OR DELETE ON dvnt_settlement.funding_sources
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.reject_allocation_change();
CREATE TRIGGER immutable_funding_debit BEFORE UPDATE OR DELETE ON dvnt_settlement.funding_debits
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.reject_allocation_change();

-- Reviewed risk-policy changes use the same budget mutex before touching any
-- policy row. Both increases and decreases invalidate all old audit snapshots.
-- BEFORE STATEMENT preserves controls→policy row lock order for bulk DML.
-- TRUNCATE takes ACCESS EXCLUSIVE before its trigger, so it cannot join that
-- lock order: reject it immediately without waiting on the controls mutex.
CREATE FUNCTION dvnt_settlement.risk_policy_changed() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'risk policy TRUNCATE is unsupported; use reviewed DELETE'; END IF;
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN NULL;
END $$;
CREATE TRIGGER settlement_risk_policy_change BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE
 ON dvnt_settlement.currency_reserves FOR EACH STATEMENT EXECUTE FUNCTION dvnt_settlement.risk_policy_changed();

-- The immutable epoch must predate all new-model checkouts. Moving it forward
-- could erase debits, so configuration is a reviewed rollout step, never an RPC.
CREATE FUNCTION dvnt_settlement.require_funding_policy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM dvnt_settlement.funding_policy WHERE singleton
   AND audit_from<=floor(extract(epoch FROM NEW.created_at))) THEN
  RAISE EXCEPTION 'source-accounted funding policy missing'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER prepared_checkout_funding_policy BEFORE INSERT ON dvnt_settlement.checkouts
 FOR EACH ROW EXECUTE FUNCTION dvnt_settlement.require_funding_policy();
CREATE OR REPLACE FUNCTION public.settlement_balance_checkpoint() RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('epoch',c.funding_epoch,'observed_at',clock_timestamp(),
  'funding_policy',CASE WHEN p.singleton IS NULL THEN NULL ELSE to_jsonb(p)-'policy_reference'-'singleton' END)
 FROM dvnt_settlement.controls c LEFT JOIN dvnt_settlement.funding_policy p ON p.singleton WHERE c.singleton;
$$;

-- Only the trusted provider adapter calls this after verifying succeeded PI,
-- separate charge, frozen economics and the actual expanded balance transaction.
CREATE FUNCTION public.settlement_record_funding_source(p_order_id uuid,p_platform_account text,p_proof jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s dvnt_settlement.orders%ROWTYPE; o public.orders%ROWTYPE;
 policy dvnt_settlement.funding_policy%ROWTYPE; prior jsonb;
BEGIN
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order_id FOR UPDATE;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT policy FROM dvnt_settlement.funding_policy WHERE singleton;
 SELECT * INTO STRICT s FROM dvnt_settlement.orders WHERE order_id=p_order_id;
 IF p_platform_account IS DISTINCT FROM policy.platform_account OR o.charge_model IS DISTINCT FROM 'separate_charges_and_transfers'
 OR p_proof->>'id' IS NULL OR p_proof->>'id' !~ '^txn_[A-Za-z0-9_]+$'
 OR p_proof->>'source' IS DISTINCT FROM s.charge_id OR p_proof->>'currency' IS DISTINCT FROM s.currency
 OR p_proof->>'type' NOT IN ('charge','payment') OR p_proof->>'type' IS NULL
 OR (p_proof->>'amount')::bigint IS DISTINCT FROM s.gross_cents
 OR (p_proof->>'fee')::bigint IS NULL OR (p_proof->>'fee')::bigint<0
 OR (p_proof->>'net')::bigint IS DISTINCT FROM s.gross_cents-(p_proof->>'fee')::bigint
 OR (p_proof->>'net')::bigint<s.distributable_cents+coalesce(o.tax_cents,0)
 OR (p_proof->>'tax')::bigint IS DISTINCT FROM coalesce(o.tax_cents,0)
 OR (p_proof->>'created')::bigint IS NULL OR (p_proof->>'created')::bigint<policy.audit_from
 OR (p_proof->>'created')::bigint>floor(extract(epoch FROM clock_timestamp()))
 OR p_proof->>'status' IS DISTINCT FROM 'available'
 THEN RAISE EXCEPTION 'source-accounted funding proof mismatch'; END IF;
 SELECT proof INTO prior FROM dvnt_settlement.funding_sources WHERE order_id=p_order_id;
 IF FOUND THEN
  IF prior IS DISTINCT FROM p_proof THEN RAISE EXCEPTION 'immutable funding source mismatch'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicate',true);
 END IF;
 INSERT INTO dvnt_settlement.funding_sources(order_id,transaction_id,proof) VALUES(p_order_id,p_proof->>'id',p_proof);
 UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton;
 RETURN jsonb_build_object('ok',true,'duplicate',false);
END $$;

-- Adapter exhausts the unfiltered platform balance-transaction list and repeats
-- the head page to detect concurrent entries. Positive unknowns contribute zero.
-- All debits persist (pending too); uncertain DB liabilities remain reserved.
CREATE FUNCTION public.settlement_record_funding_audit(p_currency text,p_available bigint,p_balance_epoch bigint,
 p_started_at timestamptz,p_platform_account text,p_livemode boolean,p_audit_from bigint,p_transactions jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE policy dvnt_settlement.funding_policy%ROWTYPE; t jsonb; prior jsonb;
 credits bigint:=0; debits bigint:=0; spendable bigint; inserted int; new_debit boolean:=false; audit_epoch bigint;
BEGIN
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT policy FROM dvnt_settlement.funding_policy WHERE singleton;
 IF p_platform_account IS DISTINCT FROM policy.platform_account OR p_livemode IS DISTINCT FROM policy.livemode
 OR p_audit_from IS DISTINCT FROM policy.audit_from OR p_balance_epoch IS DISTINCT FROM (SELECT funding_epoch FROM dvnt_settlement.controls WHERE singleton)
 OR p_started_at IS NULL OR p_started_at<clock_timestamp()-interval '60 seconds' OR p_started_at>clock_timestamp()
 OR p_currency IS NULL OR p_currency !~ '^[a-z]{3}$' OR p_available IS NULL OR p_available<0
 OR jsonb_typeof(p_transactions) IS DISTINCT FROM 'array' OR jsonb_array_length(p_transactions)>10000 THEN
  RAISE EXCEPTION 'source-accounted funding audit invalid or stale'; END IF;
 IF EXISTS(SELECT 1 FROM dvnt_settlement.funding_audits WHERE currency=p_currency AND observed_at>p_started_at) THEN
  RAISE EXCEPTION 'source-accounted funding audit stale'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p_transactions)) IS DISTINCT FROM
    (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_transactions) x) THEN RAISE EXCEPTION 'duplicate funding transaction'; END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(p_transactions) LOOP
  IF t->>'id' IS NULL OR t->>'id' !~ '^txn_[A-Za-z0-9_]+$' OR t->>'currency' IS NULL OR t->>'currency' !~ '^[a-z]{3}$'
   OR t->>'status' IS NULL OR t->>'status' NOT IN ('pending','available')
   OR t->>'type' IS NULL OR (t->>'created')::bigint IS NULL OR (t->>'created')::bigint<policy.audit_from
   OR (t->>'created')::bigint>floor(extract(epoch FROM clock_timestamp()))
   OR (t->>'amount')::bigint IS NULL OR (t->>'fee')::bigint IS NULL
   OR (t->>'net')::bigint IS DISTINCT FROM (t->>'amount')::bigint-(t->>'fee')::bigint THEN
   RAISE EXCEPTION 'invalid funding transaction'; END IF;
  IF (t->>'net')::bigint<0 THEN
   SELECT proof INTO prior FROM dvnt_settlement.funding_debits WHERE transaction_id=t->>'id';
   IF FOUND AND prior IS DISTINCT FROM t-'status' THEN RAISE EXCEPTION 'immutable funding debit mismatch'; END IF;
   INSERT INTO dvnt_settlement.funding_debits(transaction_id,currency,net_cents,proof)
    VALUES(t->>'id',t->>'currency',(t->>'net')::bigint,t-'status') ON CONFLICT(transaction_id) DO NOTHING;
   GET DIAGNOSTICS inserted=ROW_COUNT; new_debit:=new_debit OR inserted>0;
  ELSIF t->>'status'='available' AND t->>'currency'=p_currency THEN
   SELECT proof INTO prior FROM dvnt_settlement.funding_sources WHERE transaction_id=t->>'id';
   IF FOUND THEN
    IF prior-'tax' IS DISTINCT FROM t THEN RAISE EXCEPTION 'funding source transaction mismatch'; END IF;
    credits:=credits+(t->>'net')::bigint-(prior->>'tax')::bigint;
   END IF;
  END IF;
 END LOOP;
 IF new_debit THEN UPDATE dvnt_settlement.controls SET funding_epoch=funding_epoch+1 WHERE singleton; END IF;
 SELECT funding_epoch INTO audit_epoch FROM dvnt_settlement.controls WHERE singleton;
 SELECT coalesce(-sum(net_cents),0) INTO debits FROM dvnt_settlement.funding_debits WHERE currency=p_currency;
 spendable:=greatest(0,least(p_available,credits-debits));
 INSERT INTO dvnt_settlement.funding_audits VALUES(p_currency,audit_epoch,spendable,p_available,credits,debits,p_started_at,jsonb_array_length(p_transactions))
 ON CONFLICT(currency) DO UPDATE SET funding_epoch=excluded.funding_epoch,available_cents=excluded.available_cents,
 provider_available_cents=excluded.provider_available_cents,credited_cents=excluded.credited_cents,
 debited_cents=excluded.debited_cents,observed_at=excluded.observed_at,transaction_count=excluded.transaction_count;
 RETURN jsonb_build_object('ok',true,'available',spendable,'epoch',audit_epoch);
END $$;

-- Wrap LAST so external-proof/promoter rules are preserved. No old raw-balance
-- public service entrypoint remains reachable.
ALTER FUNCTION public.settlement_reserve(uuid,text,bigint,bigint) RENAME TO reserve_before_funding;
ALTER FUNCTION public.reserve_before_funding(uuid,text,bigint,bigint) SET SCHEMA dvnt_settlement;
CREATE FUNCTION public.settlement_reserve(p_allocation uuid,p_destination text,p_available bigint,p_balance_epoch bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE currency_code text; audit dvnt_settlement.funding_audits%ROWTYPE; risk_floor bigint; protected_budget bigint;
BEGIN
 SELECT o.currency INTO STRICT currency_code FROM public.orders o JOIN dvnt_settlement.allocations a ON a.order_id=o.id
  WHERE a.id=p_allocation FOR UPDATE OF o;
 PERFORM 1 FROM dvnt_settlement.controls WHERE singleton FOR UPDATE;
 SELECT * INTO audit FROM dvnt_settlement.funding_audits f
  WHERE f.currency=currency_code AND f.funding_epoch=p_balance_epoch
   AND f.funding_epoch=(SELECT funding_epoch FROM dvnt_settlement.controls WHERE singleton)
   AND f.observed_at>clock_timestamp()-interval '60 seconds' AND p_available BETWEEN 0 AND f.available_cents;
 IF NOT FOUND OR p_available IS NULL THEN
  RAISE EXCEPTION 'source-accounted funding audit missing or stale'; END IF;
 SELECT reserve_cents INTO risk_floor FROM dvnt_settlement.currency_reserves WHERE currency=currency_code;
 IF risk_floor IS NULL OR risk_floor<0 THEN RAISE EXCEPTION 'platform risk reserve funding policy missing'; END IF;
 IF risk_floor>audit.provider_available_cents THEN RAISE EXCEPTION 'insufficient unreserved funds'; END IF;
 -- Inner reserve checks L + floor <= budget, where L is this payout plus all
 -- pending/unknown sends, protected commissions and refund/dispute liabilities.
 -- Use min(actual, authenticated_source_cap + floor) only inside this call:
 --   L <= authenticated_source_cap AND L + floor <= audited actual available.
 -- Thus extra actual balance covers ONLY the buffer inequality, never a source
 -- deficit. Capital provenance is a separate operational gate.
 -- Do not persist/return this adjusted number as a source credit.
 -- Numeric addition avoids bigint overflow before the bounded cast. The same
 -- controls mutex prevents the policy trigger changing floor between these two
 -- reads; the unchanged private implementation counts every liability once.
 protected_budget:=least(audit.provider_available_cents::numeric,p_available::numeric+risk_floor::numeric)::bigint;
 RETURN dvnt_settlement.reserve_before_funding(p_allocation,p_destination,protected_budget,p_balance_epoch);
END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA dvnt_settlement FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.settlement_record_funding_source(uuid,text,jsonb),
 public.settlement_record_funding_audit(text,bigint,bigint,timestamptz,text,boolean,bigint,jsonb),
 public.settlement_reserve(uuid,text,bigint,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settlement_record_funding_source(uuid,text,jsonb),
 public.settlement_record_funding_audit(text,bigint,bigint,timestamptz,text,boolean,bigint,jsonb),
 public.settlement_reserve(uuid,text,bigint,bigint) TO service_role;


NOTIFY pgrst, 'reload schema';
COMMIT;
